/* 經濟學期中衝刺 question bank (QUIZ and MOCK).
   Progress is saved by chapter and question position, so keep existing questions in the same order:
   add new ones at the END of a chapter, and fix typos in place. */
const QUIZ={"ch1": [{"q": "A typical society strives to get the most it can from its scarce resources. At the same time, the society attempts to distribute the benefits of those resources fairly. The society faces a tradeoff between", "qz": "一個社會想從稀少資源中得到最多，同時又想把好處公平分配。這個社會面對的取捨是", "o": ["guns and butter.", "efficiency and equality.", "inflation and unemployment.", "work and leisure."], "a": 1, "e": "把餅做大 = 效率；分得公平 = 公平。", "oz": ["大砲與奶油（國防 vs 民生）", "效率與公平", "通膨與失業", "工作與休閒"], "hw": "作業 CH1-2 #1"}, {"q": "You received $300 as a gift. You can spend it today or put it in a bank for a year at 5 percent interest. The opportunity cost of spending the money today, in terms of what you could have after one year, is", "qz": "你收到 $300 禮金，可以今天花掉，或存銀行一年拿 5% 利息。用一年後能擁有的金額來看，今天花掉的機會成本是", "o": ["$0.", "$15.", "$305.", "$315."], "a": 3, "e": "一年後可以有 300 × 1.05 = 315。", "hw": "作業 CH1-2 #2"}, {"q": "Senator Bright wants to convince workers that trade with other countries is beneficial. She should argue that trade can be beneficial", "qz": "Bright 參議員想說服勞工「和其他國家貿易有好處」。她應該主張貿易有好處，因為", "o": ["only if it allows us to obtain things we couldn't make for ourselves.", "because it allows specialization, which increases total output.", "to us if we can gain and the others involved lose.", "in only a limited number of circumstances because others are self-interested."], "a": 1, "e": "貿易好處來自專業分工，總產出增加。", "oz": ["只有在能取得我們自己做不出來的東西時才有好處", "貿易讓大家專業分工，總產量增加", "只要我們賺、別人虧就有好處", "只在少數情況有好處，因為別人都自利"], "hw": "作業 CH1-2 #3"}, {"q": "The \"invisible hand\" works to promote general well-being in the economy primarily through", "qz": "「看不見的手」主要透過什麼促進整體經濟福祉？", "o": ["government intervention.", "the political process.", "people's pursuit of self-interest.", "altruism."], "a": 2, "e": "看不見的手 = 每個人追求自利，被價格引導到對社會好的結果。", "oz": ["政府干預", "政治程序", "人們追求自身利益", "利他主義"], "hw": "作業 CH1-2 #4"}, {"q": "If an externality is present in a market, economic efficiency may be enhanced by", "qz": "市場有外部性時，什麼可能提升經濟效率？", "o": ["government intervention.", "a decrease in foreign competition.", "fewer market participants.", "weaker property rights."], "a": 0, "e": "外部性是市場失靈，政府介入可能改善效率。", "oz": ["政府干預", "減少外國競爭", "減少市場參與者", "較弱的財產權"], "hw": "作業 CH1-2 #5"}, {"q": "When gasoline prices rise, consumers buy more hybrid cars. This illustrates the principle that", "qz": "油價上漲時，消費者買更多油電混合車。這說明了哪個原理？", "o": ["prices rise when the government prints too much money.", "people respond to incentives.", "people face trade-offs.", "trade can make everyone better off."], "a": 1, "e": "價格改變人的行為 = 誘因 (incentives)。", "oz": ["政府印太多錢時物價上漲", "人們會對誘因做出反應", "人們面臨取捨", "貿易能讓每個人過得更好"]}, {"q": "You win $100 and can either spend it now or save it for one year at 5 percent interest. The opportunity cost of spending the $100 now is", "qz": "你中了 $100，可以現在花掉，或存一年拿 5% 利息。現在花掉的機會成本是", "o": ["$0.", "$5.", "$100.", "$105."], "a": 3, "e": "放棄的是一年後的 100 × 1.05 = 105。"}, {"q": "When the government prints money to pay for its spending (an \"inflation tax\"), who is effectively taxed?", "qz": "政府印鈔票來支付支出（「通膨稅」），實際上是誰被課稅？", "o": ["only rich people", "people who hold money", "firms that export", "the government itself"], "a": 1, "e": "物價上漲，手上的錢變薄，持有貨幣的人被「課稅」。", "oz": ["只有有錢人", "持有現金的人", "出口廠商", "政府自己"]}, {"q": "The opportunity cost of going to college includes", "qz": "上大學的機會成本包括", "o": ["only tuition.", "only the wages you give up.", "tuition, room and board only.", "tuition and the wages you give up."], "a": 3, "e": "不管讀不讀都要吃住，伙食住宿不算；學費和放棄的薪水要算。", "oz": ["只有學費", "只有放棄的薪水", "只有學費和食宿", "學費和放棄的薪水"]}, {"q": "A rational decision maker takes an action only if the", "qz": "理性決策者只有在什麼時候才會採取行動？", "o": ["total benefit is positive.", "marginal benefit is greater than the marginal cost.", "average benefit is greater than the average cost.", "marginal benefit is less than the marginal cost."], "a": 1, "e": "理性人做邊際思考：MB > MC 才做。", "oz": ["總利益是正的", "邊際利益大於邊際成本", "平均利益大於平均成本", "邊際利益小於邊際成本"]}, {"q": "Adam Smith's \"invisible hand\" works mainly through", "qz": "亞當斯密「看不見的手」主要透過什麼運作？", "o": ["altruism.", "prices.", "government regulation.", "central planning."], "a": 1, "e": "價格引導自利的人做出對社會好的決定。", "oz": ["利他主義", "價格", "政府管制", "中央計畫"]}], "ch2": [{"q": "Instead of conducting laboratory experiments to generate data to test their theories, economists often", "qz": "經濟學家很難做實驗來產生資料檢驗理論，所以他們常常", "o": ["ask winners of the Nobel Prize to evaluate their theories.", "argue that data is impossible to collect in economics.", "gather data from historical episodes of economic change.", "assume that data would support their theories."], "a": 2, "e": "經濟學很難做實驗，所以用歷史事件的資料。", "oz": ["請諾貝爾獎得主評估理論", "主張經濟學不可能收集資料", "從歷史上的經濟事件收集資料", "直接假設資料會支持理論"], "hw": "作業 CH1-2 #6"}, {"q": "Economic models", "qz": "經濟模型", "o": ["cannot be useful if they are based on false assumptions.", "were once thought to be useful, but that is no longer true.", "must incorporate all aspects of the economy to be useful.", "can be useful, even if they are not particularly realistic."], "a": 3, "e": "模型是簡化，不完全真實也有用。", "oz": ["如果建立在不真實的假設上就沒有用", "以前被認為有用，現在已經不是了", "必須包含經濟的所有面向才有用", "就算不太真實也可以很有用"], "hw": "作業 CH1-2 #7"}, {"q": "Which of the following transactions does not take place in the markets for factors of production in the circular-flow diagram?", "qz": "在循環流程圖中，下列哪一筆交易「不是」發生在生產要素市場？", "o": ["a landowner leases land to a farmer", "a farmer hires a teenager to help with harvest", "a construction company rents trucks for its business", "a woman buys corn for dinner"], "a": 3, "e": "買玉米當晚餐 = 商品與服務市場。其他都是土地、勞動、資本。", "oz": ["地主把土地租給農夫", "農夫雇用青少年幫忙收成", "建設公司租卡車來營業", "一位女士買玉米當晚餐"], "hw": "作業 CH1-2 #8"}, {"q": "Which of the following is not an assumption of the production possibilities frontier?", "qz": "下列哪一個「不是」生產可能線（PPF）的假設？", "o": ["A country produces only two goods.", "Technology does not change.", "The amount of available resources does not change.", "There is a fixed quantity of money."], "a": 3, "e": "PPF 跟貨幣量無關。", "oz": ["一國只生產兩種商品", "技術不變", "可用資源數量不變", "貨幣數量固定"], "hw": "作業 CH1-2 #9"}, {"q": "A production possibilities frontier can shift outward if", "qz": "生產可能線（PPF）在什麼情況下會往外移？", "o": ["government increases the amount of money in the economy.", "there is a technological improvement.", "resources are shifted from one good to the other.", "the economy abandons inefficient production methods in favor of efficient ones."], "a": 1, "e": "技術進步讓 PPF 外移。(c) 是沿線移動；(d) 是從線內移到線上。", "oz": ["政府增加貨幣數量", "技術進步", "資源從一種商品移到另一種", "經濟放棄沒效率的生產方式，改用有效率的"], "hw": "作業 CH1-2 #10"}, {"q": "A production possibilities frontier is a straight line when", "qz": "生產可能線（PPF）在什麼情況下是一條直線？", "o": ["the more resources used to produce one good, the fewer are available for the other.", "an economy is interdependent and engaged in trade.", "the rate of tradeoff between the two goods is constant.", "the rate of tradeoff depends on how much of each good is produced."], "a": 2, "e": "直線 = 斜率固定 = 機會成本固定。", "oz": ["一種商品用越多資源，另一種能用的越少", "經濟彼此依賴且有貿易", "兩種商品的取捨比率固定", "取捨比率取決於各生產多少"], "hw": "作業 CH2-3 #7"}, {"q": "Economists may give conflicting policy advice because they", "qz": "經濟學家為什麼可能給出互相矛盾的政策建議？", "o": ["never use data.", "all share the same values.", "differ in scientific judgments and in values.", "only study microeconomics."], "a": 2, "e": "意見不同的兩個原因：科學判斷不同、價值觀不同。", "oz": ["他們從不用資料", "他們的價值觀都相同", "他們的科學判斷和價值觀都不同", "他們只研究個體經濟"]}, {"q": "An economy has 50,000 labor hours. A computer takes 100 hours and a ton of wheat takes 10 hours. Producing 300 computers and 3,500 tons of wheat is", "qz": "一個經濟有 50,000 勞動小時。一台電腦要 100 小時，一噸小麥要 10 小時。生產 300 台電腦和 3,500 噸小麥是", "o": ["possible but inefficient.", "not possible.", "efficient.", "on the PPF."], "a": 1, "e": "300×100 + 3500×10 = 65,000 > 50,000 小時，做不到。", "oz": ["可以做到但沒效率", "做不到", "有效率", "在 PPF 上"]}, {"q": "\"The government should raise the minimum wage\" is a", "qz": "「政府應該調高最低工資」是", "o": ["statement that can be tested with data.", "positive statement.", "macroeconomic positive statement.", "normative statement."], "a": 3, "e": "有 should → 規範 (normative)。", "oz": ["可以用資料檢驗的敘述", "實證敘述", "總體經濟的實證敘述", "規範敘述"]}, {"q": "\"Lower tax rates encourage more work and more saving\" is a", "qz": "「降低稅率會鼓勵人們多工作、多儲蓄」是", "o": ["normative statement.", "value judgment.", "positive statement.", "policy recommendation."], "a": 2, "e": "描述因果關係 → 實證 (positive)。", "oz": ["規範敘述", "價值判斷", "實證敘述", "政策建議"]}, {"q": "Which of the following is a positive statement?", "qz": "下列哪一個是實證敘述？", "o": ["Prices rise when the government increases the quantity of money.", "A tax cut is needed to stimulate the economy.", "The government should print less money.", "Society ought to require welfare recipients to look for jobs."], "a": 0, "e": "(a) 描述關係；其他都是 should／needed／ought。", "oz": ["政府增加貨幣數量時物價會上漲", "需要減稅來刺激經濟", "政府應該少印錢", "社會應該要求領救濟金的人去找工作"]}, {"q": "Which of the following is a positive statement?", "qz": "下列哪一個是實證敘述？", "o": ["Raising the minimum wage causes unemployment among unskilled workers.", "The minimum wage is unfair to small businesses.", "The government ought to raise the minimum wage.", "Workers deserve a living wage."], "oz": ["調高最低工資會造成非技術勞工失業", "最低工資對小商家不公平", "政府應該調高最低工資", "勞工應該得到足以生活的工資"], "a": 0, "e": "實證敘述是描述「世界是怎樣」，可以用資料檢驗，就算最後被證明是錯的也還是實證敘述。看到 should、ought、fair、deserve 這類價值判斷，就是規範敘述。", "h": 1}], "ch3": [{"q": "If Shawn can produce more donuts in one day than Sue can produce in one day, then", "qz": "如果 Shawn 一天能做的甜甜圈比 Sue 多，那麼", "o": ["Shawn has a comparative advantage in donuts.", "Sue has a comparative advantage in donuts.", "Shawn has an absolute advantage in donuts.", "Sue has an absolute advantage in donuts."], "a": 2, "e": "只比產量 = 絕對優勢。不知道機會成本，無法判斷比較優勢。", "oz": ["Shawn 在甜甜圈有比較利益", "Sue 在甜甜圈有比較利益", "Shawn 在甜甜圈有絕對利益", "Sue 在甜甜圈有絕對利益"], "hw": "作業 CH2-3 #8"}, {"q": "The principle of comparative advantage does not provide answers to certain questions. One of those questions is", "qz": "比較利益原理無法回答某些問題。下列哪一個是它回答不了的？", "o": ["Is it possible for specialization and trade to benefit more than one party?", "Is it possible for specialization and trade to increase total output?", "Do opportunity costs play a role in decisions to specialize?", "What determines the price at which trade takes place?"], "a": 3, "e": "比較優勢只告訴你價格範圍，不決定實際價格。", "oz": ["專業分工和貿易能不能讓不只一方受益？", "專業分工和貿易能不能增加總產量？", "機會成本在專業分工決策中有沒有作用？", "交易價格是由什麼決定的？"], "hw": "作業 CH2-3 #9"}, {"q": "In the U.S., a computer takes 100 hours and a ton of wheat 10 hours. In Japan, a computer takes 125 hours and wheat 25 hours. Which country has a comparative advantage in computers?", "qz": "美國做一台電腦要 100 小時、一噸小麥 10 小時；日本做電腦要 125 小時、小麥 25 小時。哪一國在電腦有比較利益？", "o": ["both", "Japan", "neither", "the U.S."], "a": 1, "e": "電腦機會成本：美國 100/10 = 10 噸、日本 125/25 = 5 噸 → 日本較低。", "oz": ["兩國都有", "日本", "兩國都沒有", "美國"]}, {"q": "In the same example (U.S.: computer 100 h, wheat 10 h; Japan: computer 125 h, wheat 25 h), which statement is correct?", "qz": "同一個例子（美國：電腦 100 小時、小麥 10 小時；日本：電腦 125 小時、小麥 25 小時），哪個敘述正確？", "o": ["Japan has an absolute advantage in both goods.", "The U.S. has an absolute advantage in both goods.", "The U.S. has a comparative advantage in both goods.", "Neither country gains from trade."], "a": 1, "e": "美國兩樣都用比較少小時 → 兩樣都有絕對優勢，但比較優勢只會有一樣。", "oz": ["日本兩種商品都有絕對利益", "美國兩種商品都有絕對利益", "美國兩種商品都有比較利益", "兩國都無法從貿易得利"]}, {"q": "Which statement is true?", "qz": "哪個敘述正確？", "o": ["Certain talented people have a comparative advantage in everything.", "If a trade is good for one person, it cannot be good for the other.", "Two countries can gain from trade even if one has an absolute advantage in all goods.", "If trade is good for a country, it must be good for everyone in the country."], "a": 2, "e": "貿易利得來自比較優勢，不需要絕對優勢。", "oz": ["某些有才華的人在所有事情上都有比較利益", "如果交易對一個人好，就不可能對另一個人也好", "即使一國在所有商品都有絕對利益，兩國仍能從貿易得利", "如果貿易對一國有利，就一定對該國每個人都有利"]}, {"q": "For trade to benefit both parties, the price of a good (in terms of the other good) must be", "qz": "要讓雙方都從貿易得利，一種商品的價格（用另一種商品表示）必須", "o": ["below both parties' opportunity costs.", "above both parties' opportunity costs.", "between the two parties' opportunity costs.", "equal to the absolute advantage."], "a": 2, "e": "交易價格要介於兩方機會成本之間。", "oz": ["低於雙方的機會成本", "高於雙方的機會成本", "介於雙方的機會成本之間", "等於絕對利益"]}, {"q": "Comparative advantage is based on", "qz": "比較利益是根據什麼決定的？", "o": ["money prices.", "the number of inputs used.", "opportunity cost.", "the number of workers."], "a": 2, "e": "比較優勢 = 機會成本較低。", "oz": ["貨幣價格", "使用的投入數量", "機會成本", "工人人數"]}, {"q": "A producer has an absolute advantage in a good if it", "qz": "生產者在一項商品有絕對利益，是指它", "o": ["imports the good.", "can produce it using fewer inputs.", "exports the good.", "has a lower opportunity cost."], "a": 1, "e": "絕對優勢 = 用較少投入。", "oz": ["進口這項商品", "用比較少的投入就能生產", "出口這項商品", "機會成本比較低"]}, {"q": "The gains from trade arise from", "qz": "貿易的好處來自", "o": ["government subsidies.", "tariffs.", "absolute advantage.", "comparative advantage."], "a": 3, "e": "貿易利得來自比較優勢。", "oz": ["政府補貼", "關稅", "絕對利益", "比較利益"]}, {"q": "A Freedonia worker can produce 6 corn or 2 wheat; a Sylvania worker 2 corn or 6 wheat. Each has 10 workers. Freedonia sends 30 corn to Sylvania for 30 wheat. Freedonia can now consume a maximum of", "qz": "Freedonia 一個工人能生產 6 玉米或 2 小麥；Sylvania 一個工人能生產 2 玉米或 6 小麥。兩國各有 10 個工人。Freedonia 用 30 玉米換 Sylvania 的 30 小麥。Freedonia 現在最多能消費", "o": ["30 corn and 30 wheat.", "40 corn and 30 wheat.", "40 corn and 20 wheat.", "10 corn and 40 wheat."], "a": 0, "e": "Freedonia 全做玉米 = 60，送出 30 → 剩 30 玉米 + 換來 30 小麥。", "oz": ["30 玉米和 30 小麥", "40 玉米和 30 小麥", "40 玉米和 20 小麥", "10 玉米和 40 小麥"], "hw": "作業 CH2-3 #10", "h": 1}, {"q": "A German worker takes 400 hours to make a car and 2 hours to make a case of wine. A French worker takes 600 hours for a car and X hours for wine. Germany will export cars if", "qz": "德國工人做一台車要 400 小時、一箱酒要 2 小時；法國工人做一台車要 600 小時、一箱酒要 X 小時。在什麼條件下德國會出口汽車？", "o": ["X = 3", "X = 2", "X < 3", "X > 3"], "a": 2, "e": "德國車機會成本 200 箱酒；法國 600/X。德國較低 → 200 < 600/X → X < 3。", "h": 1}], "ch4": [{"q": "The law of demand states that, other things equal, when the price of a good", "qz": "需求法則是說，在其他條件不變下，當商品價格", "o": ["falls, the demand for the good rises.", "rises, the quantity demanded of the good rises.", "rises, the demand for the good falls.", "falls, the quantity demanded of the good rises."], "a": 3, "e": "需求法則講的是「需求量」quantity demanded，方向相反。", "oz": ["下跌時，需求增加", "上漲時，需求量增加", "上漲時，需求減少", "下跌時，需求量增加"], "hw": "作業 CH4 #1"}, {"q": "A decrease in demand is represented by a", "qz": "「需求減少」在圖上表示為", "o": ["movement downward and to the right along a demand curve.", "movement upward and to the left along a demand curve.", "rightward shift of a demand curve.", "leftward shift of a demand curve."], "a": 3, "e": "需求減少 = 整條線左移。", "oz": ["沿著需求線往右下移動", "沿著需求線往左上移動", "需求線往右移", "需求線往左移"], "hw": "作業 CH4 #2"}, {"q": "Which of the following would shift the demand curve for gasoline to the right?", "qz": "下列哪一個會讓汽油的需求線往右移？", "o": ["a decrease in the price of gasoline", "an increase in consumer income, assuming gasoline is a normal good", "an increase in the price of cars, a complement for gasoline", "a decrease in the expected future price of gasoline"], "a": 1, "e": "正常財 + 所得↑ → 需求右移。(a) 沿線；(c) 左移；(d) 左移。", "oz": ["汽油價格下跌", "消費者所得增加（假設汽油是正常財）", "汽車（汽油的互補品）價格上漲", "預期未來汽油價格下跌"], "hw": "作業 CH4 #3"}, {"q": "Which of these statements best represents the law of supply?", "qz": "下列哪個敘述最能代表供給法則？", "o": ["When input prices increase, sellers produce less of the good.", "When production technology improves, sellers produce less.", "When the price of a good decreases, sellers produce less of the good.", "When sellers' supplies of a good increase, the price increases."], "a": 2, "e": "供給法則：自己價格↓ → 供給量↓。(a) 是供給線移動。", "oz": ["投入價格上漲時，賣方生產較少", "生產技術進步時，賣方生產較少", "商品價格下跌時，賣方生產較少", "賣方的供給增加時，價格上漲"], "hw": "作業 CH4 #6"}, {"q": "Wheat is the main input in the production of flour. If the price of wheat decreases, then we would expect the", "qz": "小麥是做麵粉的主要原料。如果小麥價格下跌，我們預期", "o": ["demand for flour to increase.", "demand for flour to decrease.", "supply of flour to increase.", "supply of flour to decrease."], "a": 2, "e": "投入變便宜 → 供給右移。", "oz": ["麵粉需求增加", "麵粉需求減少", "麵粉供給增加", "麵粉供給減少"], "hw": "作業 CH4 #7"}, {"q": "\"An increase in the demand for notebooks raises the quantity of notebooks demanded, but not the quantity supplied.\" This statement is", "qz": "「筆記本的需求增加，會讓筆記本的需求量增加，但供給量不會增加。」這句話", "o": ["false, because quantity supplied also rises along the supply curve.", "false, because supply shifts right.", "true.", "true only in the long run."], "a": 0, "e": "需求右移後，新均衡的供給量沿著供給線增加。", "oz": ["錯，因為沿著供給線，供給量也會增加", "錯，因為供給線右移", "對", "只有長期才對"]}, {"q": "Professional tax preparers raise the price of their services. In the market for tax-preparation software,", "qz": "專業報稅人員調漲服務價格。在報稅軟體市場中，", "o": ["supply shifts right.", "supply shifts left.", "demand shifts left.", "demand shifts right."], "a": 3, "e": "報稅師和軟體是替代品，替代品變貴 → 軟體需求右移。", "oz": ["供給右移", "供給左移", "需求左移", "需求右移"]}, {"q": "People decide to have more children. In the market for minivans,", "qz": "人們決定多生小孩。在休旅車（minivan）市場中，", "o": ["demand increases; price and quantity rise.", "supply increases; price falls.", "demand decreases; price falls.", "supply decreases; price rises."], "a": 0, "e": "買者需求增加 → 需求右移 → P↑ Q↑。", "oz": ["需求增加；價格和數量都上升", "供給增加；價格下跌", "需求減少；價格下跌", "供給減少；價格上漲"]}, {"q": "A decrease in the price of a good causes", "qz": "商品價格下跌會造成", "o": ["an increase in demand.", "a rightward shift of the demand curve.", "an increase in quantity demanded.", "a decrease in supply."], "a": 2, "e": "自己價格變 → 沿線移動 → 需求量變。", "oz": ["需求增加", "需求線右移", "需求量增加", "供給減少"]}, {"q": "If an increase in income increases the demand for a good, the good is", "qz": "如果所得增加使一項商品的需求增加，這項商品是", "o": ["a complement.", "a normal good.", "an inferior good.", "a substitute."], "a": 1, "e": "所得↑需求↑ = 正常財。", "oz": ["互補品", "正常財", "劣等財", "替代品"]}, {"q": "Hot dogs and ketchup are complements. If the price of hot dogs rises, the", "qz": "熱狗和番茄醬是互補品。如果熱狗漲價，", "o": ["demand for ketchup increases.", "demand for ketchup decreases.", "quantity of ketchup is unchanged.", "supply of ketchup increases."], "a": 1, "e": "少買熱狗 → 少用番茄醬。", "oz": ["番茄醬需求增加", "番茄醬需求減少", "番茄醬數量不變", "番茄醬供給增加"]}, {"q": "Supply increases and demand decreases at the same time. The equilibrium", "qz": "供給增加、需求同時減少。均衡", "o": ["price falls; quantity is ambiguous.", "price rises; quantity is ambiguous.", "quantity rises; price is ambiguous.", "price and quantity both fall."], "oz": ["價格下跌，數量不確定", "價格上漲，數量不確定", "數量增加，價格不確定", "價格和數量都下降"], "a": 0, "e": "供給右移讓 P↓Q↑，需求左移讓 P↓Q↓。價格兩個都往下 → 一定跌；數量一上一下 → 不確定。", "h": 1}], "ch5": [{"q": "The midpoint method is used to compute elasticity because it", "qz": "計算彈性為什麼要用中點法？", "o": ["automatically computes a positive number.", "results in an elasticity equal to the slope of the demand curve.", "gives the same answer regardless of the direction of change.", "automatically rounds quantities to the nearest whole unit."], "a": 2, "e": "中點法不管漲或跌，答案一樣。", "oz": ["它會自動算出正數", "算出的彈性會等於需求線斜率", "不論變動方向，答案都一樣", "它會自動把數量四捨五入到整數"], "hw": "作業 CH5 #2"}, {"q": "Which of the following statements is not valid when the market supply curve is vertical?", "qz": "市場供給線是垂直線時，下列哪個敘述「不成立」？", "o": ["Quantity supplied does not change when the price changes.", "Supply is perfectly inelastic.", "An increase in market demand will increase the equilibrium quantity.", "An increase in market demand will increase the equilibrium price."], "a": 2, "e": "垂直供給線：數量固定，需求增加只讓價格上漲。", "oz": ["價格變動時，供給量不變", "供給完全無彈性", "市場需求增加會讓均衡數量增加", "市場需求增加會讓均衡價格上漲"], "hw": "作業 CH5 #3"}, {"q": "Marcus says he would smoke one pack of cigarettes each day regardless of the price. If true, Marcus's", "qz": "Marcus 說不論價格多少，他每天都抽一包菸。如果這是真的，Marcus 的", "o": ["demand for cigarettes is perfectly inelastic.", "price elasticity of demand is infinite.", "income elasticity of demand is 0.", "More than one of the above is correct."], "a": 0, "e": "價格怎麼變都買一樣多 = 完全無彈性（彈性 0）。題目沒講所得，所以不能選 c。", "oz": ["香菸需求完全無彈性", "需求價格彈性是無限大", "所得彈性是 0", "以上不只一個正確"], "hw": "作業 CH5 #5"}, {"q": "When demand is inelastic, a decrease in price will cause", "qz": "需求缺乏彈性時，降價會使", "o": ["an increase in total revenue.", "a decrease in total revenue.", "no change in total revenue but an increase in quantity demanded.", "no change in total revenue but a decrease in quantity demanded."], "a": 1, "e": "缺乏彈性：價格和收益同方向，降價 → 收益↓。", "oz": ["總收益增加", "總收益減少", "總收益不變，但需求量增加", "總收益不變，但需求量減少"], "hw": "作業 CH5 #6"}, {"q": "A city wants more revenue from its municipal pools. The mayor suggests raising admission prices; the city manager suggests lowering them. Who is correct?", "qz": "市政府想增加市立泳池收入。市長建議調漲門票，市府經理建議調降。誰對？", "o": ["the mayor", "the city manager", "It depends on the price elasticity of demand.", "It depends on the construction costs of the new pool."], "a": 2, "e": "漲價或降價能不能增加收益，取決於彈性。", "oz": ["市長", "市府經理", "取決於需求價格彈性", "取決於新泳池的建造成本"], "hw": "作業 CH5 #8"}, {"q": "An airline's business travelers have inelastic demand and vacationers have elastic demand. To increase total revenue, it should", "qz": "某航空公司的商務客需求缺乏彈性，度假客需求富有彈性。要增加總收益，它應該", "o": ["increase the price to vacationers and decrease it to business travelers.", "decrease the price to vacationers and increase it to business travelers.", "decrease the price to both groups.", "increase the price to both groups."], "a": 1, "e": "缺乏彈性的漲價、富有彈性的降價，收益都會增加。", "oz": ["對度假客漲價、對商務客降價", "對度假客降價、對商務客漲價", "兩群人都降價", "兩群人都漲價"], "hw": "作業 CH5 #9"}, {"q": "After graduation your income rises a lot. You buy even more Ramen noodles; your roommate buys fewer. Your income elasticity for Ramen would", "qz": "畢業後你的所得大增。你買了更多泡麵，你的室友買得更少。你對泡麵的所得彈性會", "o": ["be negative, and your roommate's positive.", "be positive, and your roommate's negative.", "be zero, and your roommate's approach infinity.", "approach infinity, and your roommate's be zero."], "a": 1, "e": "你：所得↑買更多 → 正；室友：所得↑買更少 → 負（劣等財）。", "oz": ["是負的，室友是正的", "是正的，室友是負的", "是零，室友趨近無限大", "趨近無限大，室友是零"], "hw": "作業 CH5 #10"}, {"q": "The price elasticity of demand is calculated as", "qz": "需求價格彈性的算法是", "o": ["% change in price ÷ % change in quantity demanded.", "% change in quantity demanded ÷ % change in price.", "price × quantity.", "change in quantity ÷ change in price."], "a": 1, "e": "數量變動 % ÷ 價格變動 %。", "oz": ["價格變動 % ÷ 需求量變動 %", "需求量變動 % ÷ 價格變動 %", "價格 × 數量", "數量變動量 ÷ 價格變動量"]}, {"q": "If demand is elastic, an increase in price will", "qz": "如果需求富有彈性，漲價會", "o": ["decrease total revenue.", "not change total revenue.", "increase quantity demanded.", "increase total revenue."], "a": 0, "e": "富有彈性：價格和收益反方向。", "oz": ["減少總收益", "不改變總收益", "增加需求量", "增加總收益"]}, {"q": "If the price elasticity of demand is 0.5, demand is", "qz": "如果需求價格彈性是 0.5，需求是", "o": ["elastic.", "perfectly elastic.", "unit elastic.", "inelastic."], "a": 3, "e": "小於 1 = 缺乏彈性。", "oz": ["富有彈性", "完全有彈性", "單一彈性", "缺乏彈性"]}, {"q": "When the price of good X falls from $10 to $8, the quantity demanded of good Y rises from 20 to 25 units. Using the midpoint method, the cross-price elasticity of demand is", "qz": "X 的價格從 $10 降到 $8 時，Y 的需求量從 20 增加到 25。用中點法，交叉價格彈性是", "o": ["-1.0, and X and Y are complements.", "-1.0, and X and Y are substitutes.", "1.0, and X and Y are complements.", "1.0, and X and Y are substitutes."], "a": 0, "e": "%ΔQY = 5/22.5 = +22.2%；%ΔPX = −2/9 = −22.2%；= −1 → 互補品。", "oz": ["−1.0，X 和 Y 是互補品", "−1.0，X 和 Y 是替代品", "1.0，X 和 Y 是互補品", "1.0，X 和 Y 是替代品"], "hw": "作業 CH5 #1", "h": 1}, {"q": "The price elasticity of demand for beer is about 0.9. A policy changed the price of a case of beer from $10 to $20. Using the midpoint method, the policy should have reduced beer consumption by", "qz": "啤酒的需求價格彈性約 0.9。某政策讓一箱啤酒從 $10 漲到 $20。用中點法，這個政策應該讓啤酒消費減少", "o": ["30%.", "40%.", "60%.", "74%."], "a": 2, "e": "%ΔP = 10/15 = 66.7%；0.9 × 66.7% = 60%。", "hw": "作業 CH5 #4", "h": 1}, {"q": "Which of the following is not possible?", "qz": "下列哪一個「不可能」發生？", "o": ["Demand is elastic, and a decrease in price causes an increase in revenue.", "Demand is unit elastic, and a decrease in price causes an increase in revenue.", "Demand is inelastic, and an increase in price causes an increase in revenue.", "Demand is perfectly inelastic, and an increase in price causes an increase in revenue."], "a": 1, "e": "單一彈性時價格變動，收益不變。", "oz": ["需求富有彈性，降價使收益增加", "需求為單一彈性，降價使收益增加", "需求缺乏彈性，漲價使收益增加", "需求完全無彈性，漲價使收益增加"], "hw": "作業 CH5 #7", "h": 1}, {"q": "The price rises from $4 to $6 and the quantity supplied rises from 100 to 140. Using the midpoint method, the price elasticity of supply is about", "qz": "價格從 $4 漲到 $6，供給量從 100 增加到 140。用中點法，供給價格彈性大約是", "o": ["0.83, so supply is inelastic.", "1.2, so supply is elastic.", "0.5, so supply is inelastic.", "2.0, so supply is elastic."], "oz": ["0.83，供給缺乏彈性", "1.2，供給富有彈性", "0.5，供給缺乏彈性", "2.0，供給富有彈性"], "a": 0, "e": "%ΔQ = 40 ÷ 120 = 33.3%；%ΔP = 2 ÷ 5 = 40%。彈性 = 33.3 ÷ 40 = 0.83 < 1 → 缺乏彈性。選 1.2 的人把分子分母倒過來了。", "h": 1}], "ch6": [{"q": "Which would be the least likely result of a binding price ceiling imposed on the market for rental cars?", "qz": "對租車市場實施有約束力的價格上限，下列哪一個「最不可能」發生？", "o": ["an accumulation of dirt in the interior of rental cars", "poor engine maintenance in rental cars", "free gasoline given to people as an incentive to rent a car", "slow replacement of old rental cars"], "a": 2, "e": "價格上限造成短缺，賣方不需要提供額外好處吸引顧客。", "oz": ["租來的車內部越來越髒", "租來的車引擎保養變差", "送免費汽油吸引人租車", "舊租車很慢才汰換"], "hw": "作業 CH6 #1"}, {"q": "To say that a price ceiling is binding is to say that the price ceiling", "qz": "說價格上限「有約束力（binding）」，意思是這個價格上限", "o": ["results in a surplus.", "is set above the equilibrium price.", "causes quantity demanded to exceed quantity supplied.", "All of the above are correct."], "a": 2, "e": "有效的上限 → 短缺 → Qd > Qs。", "oz": ["造成過剩", "訂在均衡價格之上", "使需求量大於供給量", "以上皆是"], "hw": "作業 CH6 #2"}, {"q": "When a binding price ceiling is imposed on a market to benefit buyers,", "qz": "為了幫助買方而實施有約束力的價格上限時，", "o": ["every buyer in the market benefits.", "every buyer and seller benefits.", "every buyer can buy, but only if he waits in long lines.", "some buyers will not be able to buy any amount of the good."], "a": 3, "e": "短缺 → 有些人根本買不到。", "oz": ["每個買方都受益", "每個買方和賣方都受益", "每個買方都買得到，只是要排長隊", "有些買方完全買不到"], "hw": "作業 CH6 #3"}, {"q": "After a binding price floor becomes effective, a", "qz": "有約束力的價格下限生效後，", "o": ["smaller quantity of the good is bought and sold.", "larger quantity of the good is demanded.", "smaller quantity of the good is supplied.", "All of the above are correct."], "a": 0, "e": "價格被拉高 → 需求量↓，成交量 = 較小的需求量。供給量是增加的。", "oz": ["成交的數量變少", "需求量變多", "供給量變少", "以上皆是"], "hw": "作業 CH6 #4"}, {"q": "Economists generally believe that rent control is", "qz": "經濟學家普遍認為房租管制是", "o": ["an efficient and fair way to help the poor.", "inefficient but the best available means of solving a social problem.", "a highly inefficient way to help the poor raise their standard of living.", "an efficient way to allocate housing, but not a good way to help the poor."], "a": 2, "e": "經濟學家普遍反對租金管制。", "oz": ["幫助窮人有效率又公平的方法", "沒效率，但是解決社會問題最好的方法", "幫助窮人提高生活水準非常沒效率的方法", "分配住房有效率，但不是幫助窮人的好方法"], "hw": "作業 CH6 #5"}, {"q": "A tax imposed on the sellers of a good will lower the", "qz": "對賣方課稅會降低", "o": ["price paid by buyers and lower the equilibrium quantity.", "price paid by buyers and raise the equilibrium quantity.", "effective price received by sellers and lower the equilibrium quantity.", "effective price received by sellers and raise the equilibrium quantity."], "a": 2, "e": "課稅：賣方實拿↓、買方付↑、數量↓。", "oz": ["買方付的價格，並降低均衡數量", "買方付的價格，並提高均衡數量", "賣方實際拿到的價格，並降低均衡數量", "賣方實際拿到的價格，並提高均衡數量"], "hw": "作業 CH6 #6"}, {"q": "A tax on sellers will shift the", "qz": "對賣方課稅會使", "o": ["demand curve upward by the amount of the tax.", "demand curve downward by the amount of the tax.", "supply curve upward by the amount of the tax.", "supply curve downward by the amount of the tax."], "a": 2, "e": "對賣方課稅 = 成本增加 → 供給線往上移。", "oz": ["需求線往上移，移動幅度等於稅額", "需求線往下移，移動幅度等於稅額", "供給線往上移，移動幅度等於稅額", "供給線往下移，移動幅度等於稅額"], "hw": "作業 CH6 #7"}, {"q": "A $5 tax levied on the buyers of pants will cause the", "qz": "對褲子的買方課 $5 的稅，會使", "o": ["supply curve to shift down by $5.", "supply curve to shift up by $5.", "demand curve to shift down by $5.", "demand curve to shift up by $5."], "a": 2, "e": "對買方課稅 → 需求線往下移。", "oz": ["供給線往下移 $5", "供給線往上移 $5", "需求線往下移 $5", "需求線往上移 $5"], "hw": "作業 CH6 #8"}, {"q": "The price paid by buyers in a market will decrease if the government", "qz": "政府做哪件事會讓買方付的價格下降？", "o": ["increases a binding price floor.", "increases a binding price ceiling.", "decreases a tax on the good.", "All of the above are correct."], "a": 2, "e": "(a)(b) 都讓價格上升；只有減稅讓買方付的價格下降。", "oz": ["提高有約束力的價格下限", "提高有約束力的價格上限", "降低這項商品的稅", "以上皆是"], "hw": "作業 CH6 #9"}, {"q": "A price ceiling set below the equilibrium price causes", "qz": "價格上限訂在均衡價格之下會造成", "o": ["a shortage.", "no effect.", "a surplus.", "an increase in supply."], "a": 0, "e": "上限低於均衡 → binding → 短缺。", "oz": ["短缺", "沒有影響", "過剩", "供給增加"]}, {"q": "A price ceiling set above the equilibrium price", "qz": "訂在均衡價格之上的價格上限", "o": ["causes a surplus.", "is not binding and has no effect.", "raises the market price.", "causes a shortage."], "a": 1, "e": "上限在上面 → 不具約束力。", "oz": ["造成過剩", "沒有約束力，沒有影響", "提高市場價格", "造成短缺"]}, {"q": "A minimum wage set above the equilibrium wage causes", "qz": "最低工資訂在均衡工資之上會造成", "o": ["a shortage of workers.", "unemployment.", "higher employment of teenagers.", "no effect."], "a": 1, "e": "下限高於均衡 → 勞動過剩 = 失業。", "oz": ["勞工短缺", "失業", "青少年就業增加", "沒有影響"]}, {"q": "Your pay stub shows $400 was deducted for the FICA (Social Security/Medicare) tax. Which is correct?", "qz": "你的薪資單顯示被扣了 $400 的 FICA（社會安全／醫療保險）稅。哪個敘述正確？", "o": ["This tax is an example of a payback tax.", "Your employer is required by law to pay $400 to match the $400 deducted from your check.", "The $400 you paid is the true burden of the tax on you.", "All of the above are correct."], "a": 1, "e": "法律規定雇主付相同金額。但實際負擔由彈性決定，所以 c 錯。", "oz": ["這是「回饋稅」的例子", "法律規定雇主要再付 $400，配合你被扣的 $400", "你付的 $400 就是你真正的租稅負擔", "以上皆是"], "hw": "作業 CH6 #10", "h": 1}, {"q": "A binding price ceiling is raised but stays below the equilibrium price. The shortage will", "qz": "有約束力的價格上限被調高，但仍低於均衡價格。短缺會", "o": ["grow larger.", "become smaller.", "disappear.", "stay the same."], "oz": ["變大", "變小", "消失", "不變"], "a": 1, "e": "上限越接近均衡價格，需求量減少、供給量增加，兩者差距（短缺）變小。只有調到均衡以上才會完全消失。", "h": 1}], "ch7": [{"q": "Welfare economics explains which of the following in the market for televisions?", "qz": "福利經濟學可以說明電視市場的哪件事？", "o": ["The government sets the price; firms respond by producing.", "The government sets the quantity; firms respond with a price.", "The market equilibrium price maximizes the total welfare of buyers and sellers.", "The equilibrium price maximizes consumer welfare and minimizes producer profit."], "a": 2, "e": "均衡讓總剩餘最大。", "oz": ["政府訂價格，廠商跟著生產", "政府訂數量，廠商跟著訂價", "市場均衡價格讓買賣雙方的總福利最大", "均衡價格讓消費者福利最大、生產者利潤最小"], "hw": "作業 CH7 #1"}, {"q": "A demand curve reflects each of the following except the", "qz": "需求線反映了下列各項，「除了」哪一項？", "o": ["willingness to pay of all buyers in the market.", "value each buyer places on the good.", "highest price buyers are willing to pay for each quantity.", "ability of buyers to obtain the quantity they desire."], "a": 3, "e": "需求線反映願付價格，不反映買不買得到。", "oz": ["市場中所有買方的願付價格", "每個買方對商品的評價", "每個數量下買方願意付的最高價格", "買方能否買到想要的數量"], "hw": "作業 CH7 #2"}, {"q": "You get a free Cubs ticket (no resale value). Willie Nelson performs the same night; tickets cost $40 and you'd pay up to $50. At a minimum, how much must you value the Cubs game to go?", "qz": "你拿到一張免費的小熊隊球票（不能轉賣）。同一晚 Willie Nelson 開演唱會，票價 $40，你最多願意付 $50。你至少要對球賽評價多少才會去看球？", "o": ["$0", "$10", "$40", "$50"], "a": 1, "e": "放棄的是演唱會的剩餘 50 − 40 = 10。", "hw": "作業 CH7 #3"}, {"q": "Which of the following will cause an increase in producer surplus?", "qz": "下列哪一個會使生產者剩餘增加？", "o": ["a binding price ceiling", "buyers expect the price to be lower next month", "the price of a substitute increases", "income increases and the good is inferior"], "a": 2, "e": "替代品變貴 → 需求↑ → 價格和數量↑ → PS↑。其他都讓 PS↓。", "oz": ["有約束力的價格上限", "買方預期下個月價格會更低", "替代品價格上漲", "所得增加且該商品是劣等財"], "hw": "作業 CH7 #6"}, {"q": "Which of the following is correct?", "qz": "哪個敘述正確？", "o": ["Consumer surplus means there are more buyers than sellers.", "Producer surplus means there are more sellers than buyers.", "Total surplus is the area below demand and above supply, up to the equilibrium quantity.", "All of the above are correct."], "a": 2, "e": "剩餘是金額不是人數。", "oz": ["消費者剩餘是指買方比賣方多", "生產者剩餘是指賣方比買方多", "總剩餘是需求線以下、供給線以上，到均衡數量為止的面積", "以上皆是"], "hw": "作業 CH7 #7"}, {"q": "The \"invisible hand\" refers to", "qz": "「看不見的手」指的是", "o": ["the marketplace guiding self-interest into promoting general economic well-being.", "social planners intervening even in competitive markets.", "the equality resulting from market forces.", "the automatic maximization of consumer surplus."], "a": 0, "e": "亞當斯密：自利被市場引導成對社會好的結果。", "oz": ["市場引導人們的自利去促進整體經濟福祉", "社會規劃者即使在競爭市場也介入", "市場力量帶來的平等", "消費者剩餘會自動最大化"], "hw": "作業 CH7 #8"}, {"q": "If a free market for kidneys were allowed, critics argue it would", "qz": "如果允許腎臟自由買賣，批評者會說它", "o": ["not reduce the shortage of organs.", "benefit rich people but not poor people.", "be inefficient because markets are bad at allocating scarce resources.", "be inferior to a plan by a benevolent dictator."], "a": 1, "e": "批評者擔心的是公平：有錢人買得到、窮人買不到。", "oz": ["無法減少器官短缺", "只對有錢人有利、對窮人沒有好處", "沒效率，因為市場不擅長分配稀少資源", "比不上仁慈獨裁者的安排"], "hw": "作業 CH7 #9"}, {"q": "Consumer surplus is", "qz": "消費者剩餘是", "o": ["the price minus the seller's cost.", "the amount a buyer is willing to pay minus the price actually paid.", "total revenue of sellers.", "the number of extra buyers in a market."], "a": 1, "e": "CS = WTP − P。", "oz": ["價格減掉賣方成本", "買方的願付價格減掉實際付的價格", "賣方的總收益", "市場中多出來的買方人數"]}, {"q": "Producer surplus is", "qz": "生產者剩餘是", "o": ["the price received minus the seller's cost.", "the number of extra sellers in a market.", "willingness to pay minus price.", "the seller's total revenue."], "a": 0, "e": "PS = P − cost。", "oz": ["收到的價格減掉賣方成本", "市場中多出來的賣方人數", "願付價格減掉價格", "賣方的總收益"]}, {"q": "On a supply-and-demand graph, consumer surplus is the area", "qz": "在供需圖上，消費者剩餘是哪一塊面積？", "o": ["above the supply curve and below the price.", "below the demand curve and above the price.", "below the supply curve.", "between the two curves beyond equilibrium."], "a": 1, "e": "需求線以下、價格以上。", "oz": ["供給線以上、價格以下", "需求線以下、價格以上", "供給線以下", "兩條線之間、均衡以外的部分"]}, {"q": "The market demand curve passes through (quantity = 100, price = $25). If there are five buyers, then", "qz": "市場需求線通過（數量 = 100，價格 = $25）。如果有五個買方，則", "o": ["the marginal buyer's willingness to pay for the 100th unit is $25.", "the sum of the five buyers' WTP for the 100th unit is $25.", "the average of the five buyers' WTP for the 100th unit is $25.", "all five buyers are willing to pay at least $25 for the 100th unit."], "a": 0, "e": "需求線高度 = 邊際買者的 WTP。", "oz": ["邊際買方對第 100 單位的願付價格是 $25", "五個買方對第 100 單位願付價格的總和是 $25", "五個買方對第 100 單位願付價格的平均是 $25", "五個買方都願意為第 100 單位付至少 $25"], "hw": "作業 CH7 #4", "h": 1}, {"q": "Allen tutors; buyers pay $40/hour for as many hours as he wants. He is willing to tutor hour 1 for $10, hour 2 for $18, hour 3 for $28, hour 4 for $40. His producer surplus is", "qz": "Allen 當家教，學生願意以每小時 $40 買他想教的任何時數。他願意教第 1 小時的最低價是 $10、第 2 小時 $18、第 3 小時 $28、第 4 小時 $40。他的生產者剩餘是", "o": ["$40.", "$64.", "$12.", "$56."], "a": 1, "e": "(40−10)+(40−18)+(40−28)+(40−40) = 30+22+12+0 = 64。", "hw": "作業 CH7 #5", "h": 1}, {"q": "Tomato sauce and spaghetti are complements. A decrease in the price of tomatoes will", "qz": "番茄醬和義大利麵是互補品。番茄價格下跌會", "o": ["increase CS for tomato sauce and decrease PS for spaghetti.", "increase CS for tomato sauce and increase PS for spaghetti.", "decrease CS for tomato sauce and increase PS for spaghetti.", "decrease CS for tomato sauce and decrease PS for spaghetti."], "a": 1, "e": "番茄便宜 → 醬供給↑ → 醬變便宜 CS↑；醬便宜 → 麵需求↑ → 麵 PS↑。", "oz": ["增加番茄醬的消費者剩餘、減少義大利麵的生產者剩餘", "增加番茄醬的消費者剩餘、增加義大利麵的生產者剩餘", "減少番茄醬的消費者剩餘、增加義大利麵的生產者剩餘", "減少番茄醬的消費者剩餘、減少義大利麵的生產者剩餘"], "hw": "作業 CH7 #10", "h": 1}], "ch8": [{"q": "When a tax is imposed on a good, the", "qz": "對一項商品課稅時，", "o": ["supply curve always shifts.", "demand curve always shifts.", "amount buyers are willing to buy at each price always remains unchanged.", "equilibrium quantity of the good always decreases."], "a": 3, "e": "不管課誰，數量都會下降。移動哪條線看課在誰身上。", "oz": ["供給線一定會移動", "需求線一定會移動", "每個價格下買方願意買的數量一定不變", "均衡數量一定會減少"], "hw": "作業 CH8 #1"}, {"q": "If a tax shifts the supply curve downward (or to the right), we can infer that the tax was levied on", "qz": "如果一項稅讓供給線往下（往右）移，我們可以推論這項稅是課在", "o": ["buyers of the good.", "sellers of the good.", "both buyers and sellers.", "We cannot infer anything because the shift is not consistent with a tax."], "a": 3, "e": "稅只會讓供給線往上，或讓需求線往下。供給往下不是稅。", "oz": ["買方", "賣方", "買方和賣方", "無法推論，因為這種移動不符合課稅的效果"], "hw": "作業 CH8 #2"}, {"q": "One result of a tax, regardless of whether it is placed on buyers or sellers, is that the", "qz": "不論稅課在買方或賣方，都會有的一個結果是", "o": ["equilibrium quantity is unchanged.", "price the buyer effectively pays is lower.", "supply curve shifts upward by the amount of the tax.", "tax reduces the welfare of both buyers and sellers."], "a": 3, "e": "買賣雙方剩餘都減少。", "oz": ["均衡數量不變", "買方實際付的價格變低", "供給線往上移，幅度等於稅額", "稅讓買方和賣方的福利都下降"], "hw": "作業 CH8 #3"}, {"q": "For a taxed good, the area representing government's tax revenue is", "qz": "對一項商品課稅時，代表政府稅收的面積", "o": ["smaller than the area representing the loss of CS and PS caused by the tax.", "bounded by S, D, PB and PS.", "a right triangle.", "a triangle, but not necessarily a right triangle."], "a": 0, "e": "稅收（長方形）< CS+PS 損失，差額 = DWL。", "oz": ["比稅造成的消費者剩餘與生產者剩餘損失面積小", "由供給線、需求線、買方價格 PB 和賣方價格 PS 圍成", "是直角三角形", "是三角形，但不一定是直角三角形"], "hw": "作業 CH8 #4"}, {"q": "A tax is imposed on baseball bats. In which case will equilibrium quantity shrink the least?", "qz": "對棒球棒課稅。哪種情況下均衡數量減少最少？", "o": ["Buyers respond strongly, sellers weakly.", "Sellers respond strongly, buyers weakly.", "Both respond strongly.", "Both respond weakly."], "a": 3, "e": "雙方反應都弱 = 都缺乏彈性 → 數量變最少。", "oz": ["買方反應大、賣方反應小", "賣方反應大、買方反應小", "雙方反應都大", "雙方反應都小"], "hw": "作業 CH8 #6"}, {"q": "The deadweight loss of a tax is", "qz": "租稅的無謂損失是", "o": ["the increase in producer surplus.", "the fall in total surplus that results from the tax.", "the tax revenue collected.", "the fall in consumer surplus only."], "a": 1, "e": "DWL = 總剩餘減少的部分。", "oz": ["生產者剩餘的增加", "因為課稅造成的總剩餘下降", "收到的稅收", "只有消費者剩餘的下降"]}, {"q": "A tax would cause a larger deadweight loss if it were placed on", "qz": "課稅造成的無謂損失，在哪一種情況比較大？", "o": ["sunscreen than on breakfast cereal.", "salt than on cereal.", "insulin than on cereal.", "breakfast cereal than on sunscreen."], "a": 3, "e": "早餐穀片替代品多 → 需求較有彈性。", "oz": ["課在防曬乳比課在早餐穀片", "課在鹽比課在穀片", "課在胰島素比課在穀片", "課在早餐穀片比課在防曬乳"]}, {"q": "If a tax is doubled, the deadweight loss", "qz": "如果稅加倍，無謂損失", "o": ["more than doubles (about four times).", "is unchanged.", "falls by half.", "doubles."], "a": 0, "e": "DWL 跟稅的平方成正比。", "oz": ["增加超過兩倍（約四倍）", "不變", "減半", "加倍"]}, {"q": "A $4 per-unit tax decreases quantity from 2,000 to 1,700. It decreases CS by $3,000 and PS by $4,400. The deadweight loss is", "qz": "每單位 $4 的稅讓數量從 2,000 降到 1,700。消費者剩餘減少 $3,000，生產者剩餘減少 $4,400。無謂損失是", "o": ["$200.", "$400.", "$600.", "$1,200."], "a": 2, "e": "7,400 − 4 × 1,700 = 7,400 − 6,800 = 600。也可用 ½ × 4 × 300 = 600。", "hw": "作業 CH8 #5", "h": 1}, {"q": "A tax is imposed on cheese. The deadweight loss will likely be greater in the", "qz": "對起司課稅。無謂損失比較可能在哪一年比較大？", "o": ["first year, because demand and supply are more elastic in the first year.", "first year, because demand and supply are less elastic in the first year.", "eighth year, because demand and supply are more elastic in the first year.", "eighth year, because demand and supply are less elastic in the first year."], "a": 3, "e": "短期彈性小，長期彈性大 → 第八年 DWL 大。", "oz": ["第一年，因為第一年供需比較有彈性", "第一年，因為第一年供需比較沒彈性", "第八年，因為第一年供需比較有彈性", "第八年，因為第一年供需比較沒彈性"], "hw": "作業 CH8 #8", "h": 1}, {"q": "As more people become self-employed and can choose their weekly hours, the DWL from the Social Security tax would", "qz": "越來越多人自己當老闆、可以自己決定每週工時。社會安全稅的無謂損失會", "o": ["increase, and revenue increase.", "increase, and revenue decrease.", "decrease, and revenue increase.", "decrease, and revenue decrease."], "a": 1, "e": "勞動供給更有彈性 → DWL↑、稅收↓。", "oz": ["增加，稅收增加", "增加，稅收減少", "減少，稅收增加", "減少，稅收減少"], "hw": "作業 CH8 #9", "h": 1}, {"q": "A $0.50 per-unit tax creates a DWL of $100. If the tax rises to $2.50, the DWL would be", "qz": "每單位 $0.50 的稅造成 $100 的無謂損失。如果稅提高到 $2.50，無謂損失會是", "o": ["$200.", "$250.", "$500.", "$2,500."], "a": 3, "e": "稅變 5 倍 → DWL 變 25 倍 → 2,500。", "hw": "作業 CH8 #10", "h": 1}, {"q": "The supply of land is perfectly inelastic. A tax on land will", "qz": "土地的供給完全無彈性。對土地課稅會", "o": ["be borne entirely by landowners and cause no deadweight loss.", "be borne entirely by renters.", "cause a large deadweight loss.", "raise no revenue."], "oz": ["全部由地主負擔，沒有無謂損失", "全部由承租人負擔", "造成很大的無謂損失", "收不到稅"], "a": 0, "e": "供給垂直 → 數量完全不會變 → 沒有減少的交易，DWL = 0。最沒彈性的一方負擔全部的稅，所以是地主。", "h": 1}], "ch9": [{"q": "Canada forbids trade. In Canada, 1 hockey stick trades for 5 baseball bats; in other countries, for 8 bats. These facts indicate that", "qz": "加拿大禁止貿易。在加拿大，1 支冰球桿可以換 5 支棒球棒；在其他國家可以換 8 支。這表示", "o": ["if Canada allowed trade, it would export hockey sticks.", "Canada has an absolute advantage in hockey sticks.", "Canada has a comparative advantage in baseball bats.", "All of the above are correct."], "a": 0, "e": "加拿大球桿的機會成本（5 支球棒）較低 → 出口球桿。不能推論絕對優勢。", "oz": ["如果加拿大開放貿易，會出口冰球桿", "加拿大在冰球桿有絕對利益", "加拿大在棒球棒有比較利益", "以上皆是"], "hw": "作業 CH9 #1"}, {"q": "Mexico has imposed a tariff on imported chocolate. As a consequence,", "qz": "墨西哥對進口巧克力課關稅。結果", "o": ["Mexico is better off, since the tariff increases domestic employment and production.", "Mexico is better off, since the tariff results in tax revenue.", "Mexico is worse off, since PS and CS both decrease.", "Mexico is worse off, since the increase in PS is smaller than the drop in CS plus tariff revenues."], "a": 3, "e": "PS 增加 + 關稅收入 < CS 減少，差額 = DWL。", "oz": ["墨西哥變好，因為關稅增加國內就業和生產", "墨西哥變好，因為關稅帶來稅收", "墨西哥變差，因為生產者剩餘和消費者剩餘都下降", "墨西哥變差，因為生產者剩餘的增加小於消費者剩餘的減少加上關稅收入"], "hw": "作業 CH9 #2"}, {"q": "When a country allows trade and becomes an importer of a good,", "qz": "一國開放貿易後成為某商品的進口國，", "o": ["both producers and consumers become better off.", "producers better off, consumers worse off.", "producers worse off, consumers better off.", "both become worse off."], "a": 2, "e": "進口讓國內價格下跌。", "oz": ["生產者和消費者都變好", "生產者變好，消費者變差", "生產者變差，消費者變好", "雙方都變差"], "hw": "作業 CH9 #3"}, {"q": "Iceland goes from being isolated to being an exporter of coats. As a result,", "qz": "冰島從封閉變成外套的出口國。結果", "o": ["consumer surplus increases for coat consumers in Iceland.", "producer surplus increases for coat producers in Iceland.", "total surplus remains unchanged.", "other countries have a comparative advantage over Iceland in coats."], "a": 1, "e": "出口 → 價格上升 → PS↑。", "oz": ["冰島外套消費者的消費者剩餘增加", "冰島外套生產者的生產者剩餘增加", "總剩餘不變", "其他國家在外套比冰島有比較利益"], "hw": "作業 CH9 #4"}, {"q": "Opponents of free trade want the U.S. to ban imports from overseas factories paying below the U.S. minimum wage. Prohibiting such goods is likely to", "qz": "反自由貿易者希望美國禁止從付薪低於美國最低工資的海外工廠進口。禁止這些商品可能會", "o": ["cause these factories to pay the U.S. minimum wage.", "increase technological advance in poor countries.", "increase poverty in poor countries and benefit U.S. firms which compete with these imports.", "harm U.S. firms which compete with these imports."], "a": 2, "e": "窮國工作機會消失；本國競爭廠商少了對手。", "oz": ["讓這些工廠改付美國最低工資", "促進窮國的技術進步", "增加窮國的貧窮，並讓和這些進口品競爭的美國廠商受益", "傷害和這些進口品競爭的美國廠商"], "hw": "作業 CH9 #6"}, {"q": "Which of the following is not correct about the multilateral approach to free trade?", "qz": "關於用多邊方式推動自由貿易，下列哪個「不正確」？", "o": ["It has the potential to result in freer trade than the unilateral approach.", "It may have a political advantage over the unilateral approach.", "It is simpler than the unilateral approach.", "NAFTA and GATT both represent multilateral approaches."], "a": 2, "e": "多邊談判要很多國家同意，並不簡單。", "oz": ["它有可能比單邊方式帶來更自由的貿易", "它在政治上可能比單邊方式有優勢", "它比單邊方式簡單", "NAFTA 和 GATT 都是多邊方式"], "hw": "作業 CH9 #10"}, {"q": "If the domestic price without trade is below the world price, the country will", "qz": "如果沒有貿易時的國內價格低於世界價格，這個國家會", "o": ["export the good.", "impose a tariff.", "import the good.", "neither import nor export."], "a": 0, "e": "國內便宜 → 有比較優勢 → 出口。", "oz": ["出口這項商品", "課關稅", "進口這項商品", "不進口也不出口"]}, {"q": "When a country opens to trade and becomes an importer of a good,", "qz": "一國開放貿易後成為某商品的進口國，", "o": ["total surplus falls.", "producers are better off and consumers are worse off.", "both are worse off.", "consumers are better off, producers are worse off, and total surplus rises."], "a": 3, "e": "價格下跌：CS↑ PS↓ TS↑。", "oz": ["總剩餘下降", "生產者變好、消費者變差", "兩者都變差", "消費者變好、生產者變差，總剩餘增加"]}, {"q": "When a country becomes an exporter of a good,", "qz": "一國成為某商品的出口國時，", "o": ["both rise.", "both fall.", "consumer surplus rises and producer surplus falls.", "consumer surplus falls and producer surplus rises."], "a": 3, "e": "價格上升到世界價格。", "oz": ["兩種剩餘都增加", "兩種剩餘都減少", "消費者剩餘增加、生產者剩餘減少", "消費者剩餘減少、生產者剩餘增加"]}, {"q": "A major difference between tariffs and import quotas is that", "qz": "關稅和進口配額的一個主要差別是", "o": ["tariffs create deadweight losses, but quotas do not.", "tariffs help domestic consumers, and quotas help domestic producers.", "tariffs raise revenue for the government, but quotas create surplus for those who get the licenses to import.", "All of the above are correct."], "a": 2, "e": "兩者效果相似，差別在多出來的錢給誰。", "oz": ["關稅造成無謂損失，配額不會", "關稅幫助國內消費者，配額幫助國內生產者", "關稅讓政府有收入，配額的好處給了拿到進口許可的人", "以上皆是"], "hw": "作業 CH9 #5", "h": 1}]};
const MOCK={"mock-1": [{"ch": 1, "q": "A firm has already spent $10 million developing a product. Finishing it would cost another $3 million, and the finished product is expected to bring in $5 million of revenue. What should a rational firm do?", "qz": "某公司已經花了 1,000 萬開發產品。要完成還得再花 300 萬，完成後預期收入 500 萬。理性的公司該怎麼做？", "o": ["Stop, because total cost ($13 million) exceeds revenue ($5 million).", "Finish it, because the marginal benefit ($5 million) exceeds the marginal cost ($3 million).", "Stop, because the $10 million is already lost.", "It is indifferent between finishing and stopping."], "oz": ["停止，因為總成本 1,300 萬大於收入 500 萬", "完成，因為邊際利益 500 萬大於邊際成本 300 萬", "停止，因為 1,000 萬已經虧掉了", "完成或停止都一樣"], "a": 1, "e": "1,000 萬是沉沒成本（sunk cost），不管做不做都拿不回來，不能算。只比較「從現在起」多花的 300 萬和多賺的 500 萬：MB > MC，所以要完成。選 A 的人把沉沒成本算進去了。", "h": 1}, {"ch": 1, "q": "Market failure can be caused by", "qz": "市場失靈可能由什麼造成？", "o": ["high prices.", "property rights.", "externalities and market power.", "competition."], "a": 2, "e": "市場失靈兩大原因：外部性、市場力量。", "oz": ["高價格", "財產權", "外部性和市場力量", "競爭"]}, {"ch": 1, "q": "The most important determinant of a country's standard of living is", "qz": "決定一國生活水準最重要的因素是", "o": ["competition from abroad.", "the strength of labor unions.", "productivity.", "the quantity of money."], "a": 2, "e": "原理 8：生產力。", "oz": ["來自國外的競爭", "工會的力量", "生產力", "貨幣數量"]}, {"ch": 2, "q": "On a bowed-outward PPF for computers and wheat, as the economy produces more and more computers, the opportunity cost of each additional computer", "qz": "在往外凸的電腦與小麥 PPF 上，經濟生產越來越多電腦時，每多一台電腦的機會成本會", "o": ["falls.", "stays the same.", "rises.", "becomes zero."], "oz": ["下降", "不變", "上升", "變成零"], "a": 2, "e": "往外凸＝機會成本遞增。原因是資源不是同樣適合生產兩種東西：先把最適合做電腦的資源拿去做，越到後面拿來的越是擅長種小麥的資源，每台電腦要放棄的小麥越多。", "h": 1}, {"ch": 2, "q": "In the circular-flow diagram, households", "qz": "在循環流程圖中，家戶", "o": ["sell factors of production and buy goods and services.", "sell goods and services.", "buy factors of production.", "produce goods and services."], "a": 0, "e": "家計擁有勞動、土地、資本，賣給廠商；再買商品。", "oz": ["賣生產要素、買商品與服務", "賣商品與服務", "買生產要素", "生產商品與服務"]}, {"ch": 2, "q": "A production possibilities frontier that is bowed outward shows", "qz": "往外凸的生產可能線表示", "o": ["decreasing opportunity cost.", "increasing opportunity cost.", "no opportunity cost.", "constant opportunity cost."], "a": 1, "e": "外凸 = 越做某商品，機會成本越高。", "oz": ["機會成本遞減", "機會成本遞增", "沒有機會成本", "機會成本固定"]}, {"ch": 3, "q": "In one hour, a worker in Country A can make 6 shirts or 3 phones, and a worker in Country B can make 2 shirts or 2 phones. Which statement is correct?", "qz": "一小時內，A 國工人能做 6 件襯衫或 3 支手機，B 國工人能做 2 件襯衫或 2 支手機。哪個敘述正確？", "o": ["A has a comparative advantage in both goods.", "A has a comparative advantage in shirts, and B has one in phones.", "B has a comparative advantage in shirts.", "Neither country can gain from trade."], "oz": ["A 國兩種商品都有比較利益", "A 國在襯衫有比較利益，B 國在手機有比較利益", "B 國在襯衫有比較利益", "兩國都無法從貿易得利"], "a": 1, "e": "A 國兩種都有絕對利益，但比較利益看機會成本：1 件襯衫 A 要放棄 0.5 支手機、B 要放棄 1 支 → A 在襯衫便宜。1 支手機 A 要放棄 2 件襯衫、B 只要 1 件 → B 在手機便宜。沒有人能兩種都有比較利益。", "h": 1}, {"ch": 3, "q": "Which of the following is possible?", "qz": "下列哪一個可能發生？", "o": ["A person has an absolute advantage in both goods.", "A person has a comparative advantage in both goods.", "Both (a) and (b).", "Neither (a) nor (b)."], "a": 0, "e": "絕對優勢可以兩樣都有；比較優勢不行。", "oz": ["一個人在兩種商品都有絕對利益", "一個人在兩種商品都有比較利益", "(a) 和 (b) 都可能", "(a) 和 (b) 都不可能"]}, {"ch": 3, "q": "An American worker can make 4 cars or 10 tons of grain per year; a Japanese worker 4 cars or 5 tons of grain. Which country has a comparative advantage in grain?", "qz": "一個美國工人每年能做 4 台車或 10 噸穀物；一個日本工人能做 4 台車或 5 噸穀物。哪一國在穀物有比較利益？", "o": ["both", "neither", "the U.S.", "Japan"], "a": 2, "e": "1 噸穀物機會成本：美 0.4 車、日 0.8 車 → 美國較低。", "oz": ["兩國都有", "兩國都沒有", "美國", "日本"]}, {"ch": 3, "q": "If a country's opportunity cost of 1 unit of X is 4 units of Y, its opportunity cost of 1 unit of Y is", "qz": "如果一國生產 1 單位 X 的機會成本是 4 單位 Y，那麼它生產 1 單位 Y 的機會成本是", "o": ["0 units of X.", "1 unit of X.", "4 units of X.", "1/4 unit of X."], "a": 3, "e": "兩者互為倒數。"}, {"ch": 4, "q": "A frost destroys much of the orange crop. Which statement correctly describes the market for orange juice?", "qz": "一場霜害毀掉大量柳橙。哪個敘述正確描述柳橙汁市場？", "o": ["Demand decreases and supply decreases.", "Supply decreases, and the quantity demanded decreases.", "Supply decreases and demand increases.", "Quantity supplied decreases and demand decreases."], "oz": ["需求減少，供給也減少", "供給減少，需求量減少", "供給減少，需求增加", "供給量減少，需求減少"], "a": 1, "e": "原料少了 → 供給線左移（supply decreases）→ 價格上漲 → 沿著需求線移動，是「需求量」減少，需求線本身沒動。選 A 的人把「需求量」和「需求」搞混了。", "h": 1}, {"ch": 4, "q": "Pizza and hamburgers are substitutes. If the price of pizza rises, the demand for hamburgers", "qz": "披薩和漢堡是替代品。如果披薩漲價，漢堡的需求會", "o": ["decreases.", "does not change.", "becomes vertical.", "increases."], "a": 3, "e": "替代品變貴 → 需求右移。", "oz": ["減少", "不變", "變成垂直", "增加"]}, {"ch": 4, "q": "Events lead oil field owners to expect higher oil prices in the future. The current supply of oil will", "qz": "某些事件讓油田主人預期未來油價會上漲。目前石油的供給會", "o": ["not change.", "become vertical.", "increase.", "decrease."], "a": 3, "e": "預期未來漲價 → 現在留著不賣。", "oz": ["不變", "變成垂直", "增加", "減少"]}, {"ch": 4, "q": "If both demand and supply increase, the equilibrium", "qz": "如果需求和供給都增加，均衡", "o": ["price falls; quantity is ambiguous.", "price rises; quantity is ambiguous.", "quantity rises; price is ambiguous.", "price and quantity both fall."], "a": 2, "e": "兩條線都右移 → 數量一定增加。", "oz": ["價格下跌，數量不確定", "價格上漲，數量不確定", "數量增加，價格不確定", "價格和數量都下降"]}, {"ch": 4, "q": "In a perfectly competitive market, buyers and sellers are", "qz": "在完全競爭市場中，買方和賣方都是", "o": ["price makers.", "unable to trade.", "controlled by the government.", "price takers."], "a": 3, "e": "人很多、商品相同 → 都是價格接受者。", "oz": ["價格制定者", "無法交易", "被政府控制", "價格接受者"]}, {"ch": 5, "q": "Demand is P = 100 − Q. At a price of $75, demand is", "qz": "需求是 P = 100 − Q。價格 $75 時，需求是", "o": ["elastic.", "inelastic.", "unit elastic.", "perfectly inelastic."], "oz": ["富有彈性", "缺乏彈性", "單一彈性", "完全無彈性"], "a": 0, "e": "直線需求線的中點是兩個截距的一半：P = 50、Q = 50，那裡彈性 = 1。P = 75 在中點以上（價高量少），彈性 > 1，所以是富有彈性。", "h": 1}, {"ch": 5, "q": "A vertical demand curve is", "qz": "垂直的需求線是", "o": ["perfectly inelastic.", "elastic.", "unit elastic.", "perfectly elastic."], "a": 0, "e": "垂直 = 完全無彈性 (elasticity = 0)。", "oz": ["完全無彈性", "富有彈性", "單一彈性", "完全有彈性"]}, {"ch": 5, "q": "Which good is likely to have the most elastic demand?", "qz": "哪一種商品的需求最可能最有彈性？", "o": ["gasoline in the short run", "salt", "a specific brand of breakfast cereal", "insulin"], "a": 2, "e": "替代品多、定義窄 → 彈性大。", "oz": ["短期的汽油", "鹽", "某一個特定品牌的早餐穀片", "胰島素"]}, {"ch": 5, "q": "If the income elasticity of demand for a good is negative, the good is", "qz": "如果一項商品的所得彈性是負的，它是", "o": ["a luxury.", "a normal good.", "a substitute.", "an inferior good."], "a": 3, "e": "所得↑ 需求↓ = 劣等財。", "oz": ["奢侈品", "正常財", "替代品", "劣等財"]}, {"ch": 5, "q": "The government increases drug interdiction, reducing the supply of illegal drugs. Because demand is inelastic, drug-related crime will likely", "qz": "政府加強緝毒，使非法毒品供給減少。因為需求缺乏彈性，和毒品有關的犯罪可能會", "o": ["increase.", "disappear.", "decrease.", "not change."], "a": 0, "e": "價格大漲、總支出增加 → 為買毒的犯罪增加。", "oz": ["增加", "消失", "減少", "不變"]}, {"ch": 6, "q": "Demand is QD = 100 − 5P and supply is QS = 5P. If the government sets a price floor of $12, there will be a", "qz": "需求 QD = 100 − 5P，供給 QS = 5P。如果政府訂價格下限 $12，會有", "o": ["surplus of 20 units.", "shortage of 20 units.", "surplus of 10 units.", "no effect, because the floor is not binding."], "oz": ["過剩 20 單位", "短缺 20 單位", "過剩 10 單位", "沒有影響，因為下限沒有約束力"], "a": 0, "e": "均衡：100 − 5P = 5P → P = 10、Q = 50。下限 12 高於 10 → 有約束力。QD = 100 − 60 = 40，QS = 60 → 過剩 60 − 40 = 20。", "h": 1}, {"ch": 6, "q": "Compared with the short run, the shortage caused by rent control in the long run is", "qz": "和短期相比，房租管制在長期造成的短缺", "o": ["larger.", "zero.", "smaller.", "the same."], "a": 0, "e": "長期供需更有彈性 → 短缺更大。", "oz": ["更大", "是零", "更小", "一樣"]}, {"ch": 6, "q": "The burden of a tax falls more heavily on the side of the market that is", "qz": "租稅負擔比較重地落在市場中哪一邊？", "o": ["less elastic.", "larger.", "legally required to pay.", "more elastic."], "a": 0, "e": "彈性小的一方較難離開市場 → 負擔多。", "oz": ["比較沒彈性的一邊", "人數比較多的一邊", "法律規定要繳稅的一邊", "比較有彈性的一邊"]}, {"ch": 6, "q": "Tax incidence depends on", "qz": "租稅歸宿取決於", "o": ["the size of the government.", "whether buyers or sellers are legally required to pay.", "the elasticities of supply and demand.", "the number of sellers only."], "a": 2, "e": "和法律規定誰繳無關。", "oz": ["政府的規模", "法律規定買方還是賣方繳稅", "供給和需求的彈性", "只看賣方人數"]}, {"ch": 7, "q": "Demand is P = 40 − Q. If the price falls from $20 to $15, consumer surplus increases by", "qz": "需求是 P = 40 − Q。價格從 $20 降到 $15 時，消費者剩餘增加多少？", "o": ["$112.50", "$50", "$312.50", "$100"], "oz": ["$112.50", "$50", "$312.50", "$100"], "a": 0, "e": "P = 20 時 Q = 20，CS = ½ × 20 × 20 = 200。P = 15 時 Q = 25，CS = ½ × 25 × 25 = 312.5。增加 312.5 − 200 = 112.5。$312.50 是新的 CS，不是增加量。", "h": 1}, {"ch": 7, "q": "Four buyers have willingness to pay of $300, $250, $175, and $125. If the price is $220, total consumer surplus is", "qz": "四個買方的願付價格是 $300、$250、$175、$125。如果價格是 $220，總消費者剩餘是", "o": ["$80.", "$110.", "$135.", "$330."], "a": 1, "e": "只有 300、250 買：80 + 30 = 110。", "h": 1}, {"ch": 7, "q": "Three sellers have costs of $10, $20, and $35. If the price is $25, total producer surplus is", "qz": "三個賣方的成本是 $10、$20、$35。如果價格是 $25，總生產者剩餘是", "o": ["$25.", "$20.", "$15.", "$40."], "a": 1, "e": "15 + 5 = 20；成本 35 的不賣。"}, {"ch": 7, "q": "Markets may fail to allocate resources efficiently because of", "qz": "市場可能無法有效率分配資源，原因是", "o": ["low prices.", "producer surplus.", "market power and externalities.", "willingness to pay."], "a": 2, "e": "市場失靈：市場力量、外部性。", "oz": ["低價格", "生產者剩餘", "市場力量和外部性", "願付價格"]}, {"ch": 8, "q": "A $6 per-unit tax reduces the quantity sold from 100 to 80 (linear curves). Tax revenue and deadweight loss are", "qz": "每單位 $6 的稅讓成交量從 100 降到 80（直線供需）。稅收和無謂損失分別是", "o": ["revenue $480, DWL $60.", "revenue $600, DWL $120.", "revenue $600, DWL $60.", "revenue $480, DWL $120."], "oz": ["稅收 $480，無謂損失 $60", "稅收 $600，無謂損失 $120", "稅收 $600，無謂損失 $60", "稅收 $480，無謂損失 $120"], "a": 0, "e": "稅收 = 稅額 × 課稅後數量 = 6 × 80 = 480（用 100 就錯了）。DWL = ½ × 稅額 × 數量減少 = ½ × 6 × 20 = 60。", "h": 1}, {"ch": 8, "q": "The deadweight loss of a tax is larger when", "qz": "在什麼情況下租稅的無謂損失比較大？", "o": ["supply and demand are more elastic.", "the tax is smaller.", "the tax is imposed on buyers.", "supply and demand are less elastic."], "a": 0, "e": "彈性越大，數量掉越多。", "oz": ["供給和需求比較有彈性", "稅比較小", "稅課在買方", "供給和需求比較沒彈性"]}, {"ch": 8, "q": "The deadweight loss of a tax on heating oil is likely to be", "qz": "對暖氣用油課稅的無謂損失可能", "o": ["larger in the fifth year than in the first year.", "zero in the long run.", "larger in the first year than in the fifth year.", "the same every year."], "a": 0, "e": "長期彈性大 → DWL 大。", "oz": ["第五年比第一年大", "長期是零", "第一年比第五年大", "每年都一樣"]}, {"ch": 8, "q": "Which statement is true?", "qz": "哪個敘述正確？", "o": ["A tax with no deadweight loss cannot raise any revenue.", "A tax that raises no revenue can still have a deadweight loss.", "Tax revenue always equals the deadweight loss.", "A tax never reduces the quantity sold."], "a": 1, "e": "稅高到沒人交易：稅收 0，DWL 最大。", "oz": ["沒有無謂損失的稅不可能有稅收", "收不到稅的稅仍然可能有無謂損失", "稅收一定等於無謂損失", "課稅絕不會讓成交量減少"], "h": 1}, {"ch": 9, "q": "Without trade, the domestic price of a good is $6. The world price is $4. When the country opens to free trade,", "qz": "沒有貿易時某商品國內價格是 $6，世界價格是 $4。開放自由貿易後，", "o": ["it exports, producer surplus rises, and consumer surplus falls.", "it imports, consumer surplus rises by more than producer surplus falls.", "it imports, and total surplus falls.", "nothing changes because the country is small."], "oz": ["它出口，生產者剩餘增加，消費者剩餘減少", "它進口，消費者剩餘增加的比生產者剩餘減少的多", "它進口，總剩餘下降", "沒有任何改變，因為它是小國"], "a": 1, "e": "世界價格比國內低 → 進口，國內價格降到 4。消費者得利、生產者受損，但消費者賺的比生產者虧的多，總剩餘增加。", "h": 1}, {"ch": 9, "q": "A tariff on an imported good", "qz": "對進口品課關稅會", "o": ["raises the domestic price and reduces imports.", "lowers the domestic price.", "increases imports.", "has no effect on domestic producers."], "a": 0, "e": "國內價格 = PW + T。", "oz": ["提高國內價格並減少進口", "降低國內價格", "增加進口", "對國內生產者沒有影響"]}, {"ch": 9, "q": "The main difference between a tariff and an import quota is", "qz": "關稅和進口配額的主要差別是", "o": ["tariffs help consumers.", "who receives the extra money: the government (tariff) or license holders (quota).", "only quotas cause deadweight loss.", "only tariffs raise prices."], "a": 1, "e": "效果類似，差在錢給誰。", "oz": ["關稅幫助消費者", "多出來的錢給誰：政府（關稅）或拿到許可的人（配額）", "只有配額造成無謂損失", "只有關稅讓價格上漲"]}], "mock-2": [{"ch": 1, "q": "Which of the following best illustrates the short-run tradeoff between inflation and unemployment?", "qz": "下列哪一個最能說明通膨與失業的短期取捨？", "o": ["The central bank slows money growth to fight inflation, and unemployment rises for a while.", "Higher productivity raises living standards over decades.", "Printing too much money raises prices in the long run.", "Trade lets countries specialize in what they do best."], "oz": ["央行放慢貨幣成長來對抗通膨，失業率暫時上升", "生產力提高讓幾十年來的生活水準上升", "長期印太多錢讓物價上漲", "貿易讓各國專精自己最擅長的事"], "a": 0, "e": "原理 10：短期內社會面臨通膨與失業的取捨。壓低通膨（減少貨幣）會讓失業暫時上升。C 是原理 9（長期），B 是原理 8，D 是原理 5。", "h": 1}, {"ch": 1, "q": "Which government policy is motivated mainly by a concern for equality?", "qz": "哪一項政府政策主要是出於公平的考量？", "o": ["laws against drunk driving", "breaking up a monopoly", "banning smoking in public places", "higher income tax rates for people with higher incomes"], "a": 3, "e": "累進稅是重分配 = 公平。其他是效率。", "oz": ["禁止酒駕的法律", "拆分獨占企業", "禁止在公共場所吸菸", "對高所得的人課較高的所得稅率"]}, {"ch": 1, "q": "In the long run, inflation is caused mainly by", "qz": "長期來看，通貨膨脹主要是由什麼造成？", "o": ["higher wages.", "international trade.", "excessive growth in the quantity of money.", "high unemployment."], "a": 2, "e": "原理 9：印太多錢。", "oz": ["較高的工資", "國際貿易", "貨幣數量成長過快", "高失業率"]}, {"ch": 2, "q": "An economy moves from a point inside its PPF to a point on the PPF with more of both goods. This shows", "qz": "一個經濟從 PPF 內部的一點移到 PPF 上、兩種商品都比較多的一點。這代表", "o": ["economic growth that shifts the PPF outward.", "a move from inefficient to efficient production, with no shift of the PPF.", "an increase in opportunity cost.", "a technological advance in one good only."], "oz": ["經濟成長，PPF 往外移", "從沒效率變成有效率的生產，PPF 沒有移動", "機會成本增加", "只有一種商品的技術進步"], "a": 1, "e": "PPF 本身沒動，是原本有閒置資源（例如失業）被用起來，所以兩種都能變多而不用犧牲。經濟成長才是 PPF 往外移。", "h": 1}, {"ch": 2, "q": "Stuart earns $8 per hour working at a fast-food restaurant. In the circular-flow diagram, this takes place in the market for", "qz": "Stuart 在速食店打工時薪 $8。在循環流程圖中，這發生在哪個市場？", "o": ["goods and services.", "financial assets.", "government services.", "factors of production."], "a": 3, "e": "勞動是生產要素。", "oz": ["商品與服務市場", "金融資產市場", "政府服務市場", "生產要素市場"]}, {"ch": 2, "q": "The slope of the PPF measures", "qz": "生產可能線（PPF）的斜率衡量的是", "o": ["the total output of the economy.", "the price of the good on the vertical axis.", "the opportunity cost of the good on the horizontal axis.", "the amount of money in the economy."], "a": 2, "e": "斜率 = 橫軸商品的機會成本。", "oz": ["經濟的總產出", "縱軸商品的價格", "橫軸商品的機會成本", "經濟中的貨幣數量"]}, {"ch": 3, "q": "In the same example (A: 6 shirts or 3 phones; B: 2 shirts or 2 phones), at which price of one phone would both countries gain from trade?", "qz": "同一個例子（A：6 襯衫或 3 手機；B：2 襯衫或 2 手機），1 支手機換多少襯衫時，兩國都能得利？", "o": ["0.5 shirt", "1.5 shirts", "2.5 shirts", "3 shirts"], "oz": ["0.5 件襯衫", "1.5 件襯衫", "2.5 件襯衫", "3 件襯衫"], "a": 1, "e": "手機的機會成本：B 是 1 件襯衫、A 是 2 件襯衫。交易價格要在兩者之間（1 到 2 件）雙方才都划算，所以是 1.5 件。", "h": 1}, {"ch": 3, "q": "Argentina: 1 lb of coffee takes 2 hours, 1 bottle of wine takes 4 hours. Brazil: coffee 1 hour, wine 5 hours. Which country has a comparative advantage in wine?", "qz": "阿根廷：1 磅咖啡要 2 小時，1 瓶酒要 4 小時。巴西：咖啡 1 小時，酒 5 小時。哪一國在酒有比較利益？", "o": ["neither", "both", "Argentina", "Brazil"], "a": 2, "e": "紅酒機會成本：阿根廷 2 磅咖啡、巴西 5 磅。", "oz": ["兩國都沒有", "兩國都有", "阿根廷", "巴西"]}, {"ch": 3, "q": "Pat takes 2 hours to make a pizza and 4 hours to brew a gallon of root beer. Kris takes 4 hours and 6 hours. At which price of pizza (in gallons of root beer) do both gain?", "qz": "Pat 做一個披薩要 2 小時、釀 1 加侖沙士要 4 小時；Kris 分別要 4 小時和 6 小時。披薩的價格（用幾加侖沙士表示）是多少時，兩人都能得利？", "o": ["0.4 gallon", "0.8 gallon", "1 gallon", "0.6 gallon"], "a": 3, "e": "pizza 機會成本：Pat 0.5、Kris 0.67，價格要在中間。", "h": 1}, {"ch": 3, "q": "Maria can read 20 pages of economics or 50 pages of sociology in an hour. Her opportunity cost of reading 100 pages of sociology is", "qz": "Maria 一小時能讀 20 頁經濟學或 50 頁社會學。她讀 100 頁社會學的機會成本是", "o": ["20 pages of economics.", "250 pages of economics.", "50 pages of economics.", "40 pages of economics."], "a": 3, "e": "100 頁社會學要 2 小時 → 放棄 40 頁經濟。", "oz": ["20 頁經濟學", "250 頁經濟學", "50 頁經濟學", "40 頁經濟學"]}, {"ch": 4, "q": "The price of coffee beans rises, and at the same time a study reports that coffee is good for health. In the coffee market,", "qz": "咖啡豆漲價，同時有研究說咖啡有益健康。在咖啡市場中，", "o": ["price rises; quantity is ambiguous.", "price falls; quantity is ambiguous.", "quantity rises; price is ambiguous.", "price and quantity both rise."], "oz": ["價格上漲，數量不確定", "價格下跌，數量不確定", "數量增加，價格不確定", "價格和數量都上升"], "a": 0, "e": "咖啡豆是投入 → 供給左移（P↑ Q↓）；有益健康 → 需求右移（P↑ Q↑）。兩個都讓價格漲，所以價格一定漲；數量一增一減，看誰移得多，不確定。", "h": 1}, {"ch": 4, "q": "If people expect the price of gasoline to rise next week, the current demand for gasoline will", "qz": "如果人們預期下週汽油會漲價，現在汽油的需求會", "o": ["not change.", "decrease.", "become perfectly elastic.", "increase."], "a": 3, "e": "預期未來漲價 → 現在先買。", "oz": ["不變", "減少", "變成完全有彈性", "增加"]}, {"ch": 4, "q": "If the market price is above the equilibrium price, there is a", "qz": "如果市場價格高於均衡價格，就會有", "o": ["shortage, and price will rise.", "surplus, and price will fall.", "surplus, and price will rise.", "shortage, and price will fall."], "a": 1, "e": "價格太高 → 過剩 → 賣方降價。", "oz": ["短缺，價格會上漲", "過剩，價格會下跌", "過剩，價格會上漲", "短缺，價格會下跌"]}, {"ch": 4, "q": "In a market, the price rose and the quantity sold fell. The most likely cause is a(n)", "qz": "某市場價格上漲、成交量下降。最可能的原因是", "o": ["increase in supply.", "decrease in demand.", "increase in demand.", "decrease in supply."], "a": 3, "e": "P 和 Q 反方向 → 供給動；P↑ → 供給減少。", "oz": ["供給增加", "需求減少", "需求增加", "供給減少"]}, {"ch": 4, "q": "The market demand curve is found by", "qz": "市場需求線是怎麼得到的？", "o": ["multiplying price by quantity.", "adding individual demand curves vertically.", "averaging individual prices.", "adding individual demand curves horizontally."], "a": 3, "e": "同一價格下把數量加起來 = 水平加總。", "oz": ["價格乘以數量", "把個別需求線垂直相加", "把個別價格平均", "把個別需求線水平相加"]}, {"ch": 5, "q": "Using the midpoint method, the price rises from $200 to $250 and quantity demanded falls from 12 to 8. The price elasticity of demand is about", "qz": "用中點法：價格從 $200 漲到 $250，需求量從 12 降到 8。需求價格彈性大約是", "o": ["1.0", "2.5", "1.8", "0.55"], "a": 2, "e": "%ΔQ = 4/10 = 40%；%ΔP = 50/225 = 22.2%；40/22.2 = 1.8。", "h": 1}, {"ch": 5, "q": "Demand is P = 100 − Q and the current price is $50. A small price cut will", "qz": "需求是 P = 100 − Q，目前價格 $50。稍微降價會", "o": ["raise total revenue.", "lower total revenue.", "leave total revenue almost unchanged.", "make demand perfectly elastic."], "oz": ["增加總收益", "減少總收益", "總收益幾乎不變", "讓需求變成完全有彈性"], "a": 2, "e": "P = 50 是直線需求線的中點，彈性 = 1，總收益 TR = 50 × 50 = 2,500 是最大值。單一彈性時價格小幅變動，收益幾乎不變。", "h": 1}, {"ch": 5, "q": "The price elasticity of demand for gasoline is usually", "qz": "汽油的需求價格彈性通常", "o": ["zero in the long run.", "the same in the short run and the long run.", "greater in the short run than in the long run.", "greater in the long run than in the short run."], "a": 3, "e": "時間越長越能調整 → 長期彈性大。", "oz": ["長期是零", "短期和長期一樣", "短期比長期大", "長期比短期大"]}, {"ch": 5, "q": "If the cross-price elasticity of demand between two goods is positive, the goods are", "qz": "如果兩種商品的交叉價格彈性是正的，它們是", "o": ["inferior goods.", "substitutes.", "complements.", "normal goods."], "a": 1, "e": "交叉彈性 > 0 = 替代品。", "oz": ["劣等財", "替代品", "互補品", "正常財"]}, {"ch": 5, "q": "The supply of beachfront property is inelastic. If demand doubles, the", "qz": "海景房的供給缺乏彈性。如果需求加倍，", "o": ["quantity rises a lot and price rises a little.", "price falls.", "quantity falls.", "price rises a lot and quantity rises a little."], "a": 3, "e": "供給缺乏彈性 → 需求增加主要反映在價格。", "oz": ["數量大增、價格小漲", "價格下跌", "數量減少", "價格大漲、數量小增"]}, {"ch": 6, "q": "Legislators want gas stations, not drivers, to bear a gasoline tax, so they make gas stations legally pay it. Which is correct?", "qz": "立法者希望汽油稅由加油站而不是駕駛人負擔，所以規定由加油站繳稅。哪個敘述正確？", "o": ["Gas stations will bear the whole tax.", "Drivers will bear none of the tax.", "The split of the burden depends on the elasticities of supply and demand, not on who legally pays.", "The tax will not change the price drivers pay."], "oz": ["加油站會負擔全部的稅", "駕駛人完全不用負擔", "負擔怎麼分取決於供需彈性，跟法律規定誰繳無關", "這項稅不會改變駕駛人付的價格"], "a": 2, "e": "租稅歸宿（tax incidence）只看彈性，誰比較沒彈性誰負擔比較多。課在賣方或買方，最後的結果完全一樣。", "h": 1}, {"ch": 6, "q": "A tax on buyers of a good shifts the", "qz": "對買方課稅會使", "o": ["demand curve down by the amount of the tax.", "demand curve up by the amount of the tax.", "supply curve up by the amount of the tax.", "supply curve down by the amount of the tax."], "a": 0, "e": "對買方課稅 → 需求線往下移。", "oz": ["需求線往下移，幅度等於稅額", "需求線往上移，幅度等於稅額", "供給線往上移，幅度等於稅額", "供給線往下移，幅度等於稅額"]}, {"ch": 6, "q": "If demand is very elastic and supply is very inelastic, a tax will be borne mostly by", "qz": "如果需求非常有彈性、供給非常沒彈性，稅主要由誰負擔？", "o": ["the government.", "sellers.", "buyers and sellers equally.", "buyers."], "a": 1, "e": "賣方彈性小 → 賣方負擔多。", "oz": ["政府", "賣方", "買賣雙方平分", "買方"]}, {"ch": 6, "q": "Supply is QS = 2P and demand is QD = 300 − P. With a price ceiling of $90, there is a", "qz": "供給是 QS = 2P，需求是 QD = 300 − P。價格上限訂在 $90 時，會有", "o": ["surplus of 30.", "no shortage or surplus.", "shortage of 30.", "shortage of 90."], "a": 2, "e": "QS = 180、QD = 210 → 短缺 30。", "oz": ["過剩 30", "沒有短缺也沒有過剩", "短缺 30", "短缺 90"], "h": 1}, {"ch": 7, "q": "If a market produces more than the equilibrium quantity, then", "qz": "如果市場生產的數量超過均衡數量，則", "o": ["total surplus rises because more goods are available.", "the extra units cost more to produce than buyers value them, so total surplus falls.", "consumer surplus and total surplus both rise.", "total surplus is unchanged."], "oz": ["總剩餘增加，因為商品變多", "多生產的那些單位，成本高於買方的評價，所以總剩餘下降", "消費者剩餘和總剩餘都增加", "總剩餘不變"], "a": 1, "e": "超過均衡後，供給線（成本）在需求線（評價）之上，每多做一單位都是「花 10 元做出只值 7 元的東西」，總剩餘變小。生產太少或太多都沒效率。", "h": 1}, {"ch": 7, "q": "Melissa buys an iPhone for $240 and gets consumer surplus of $160. Her willingness to pay is", "qz": "Melissa 用 $240 買了一支 iPhone，得到 $160 的消費者剩餘。她的願付價格是", "o": ["$400.", "$160.", "$80.", "$240."], "a": 0, "e": "WTP = 240 + 160。"}, {"ch": 7, "q": "Total surplus equals", "qz": "總剩餘等於", "o": ["consumer surplus minus producer surplus.", "price times quantity.", "value to buyers minus cost to sellers.", "tax revenue plus producer surplus."], "a": 2, "e": "CS + PS = 買方價值 − 賣方成本。", "oz": ["消費者剩餘減生產者剩餘", "價格乘以數量", "買方的評價減賣方的成本", "稅收加生產者剩餘"]}, {"ch": 7, "q": "When the price of a good rises, consumer surplus falls because", "qz": "商品漲價時，消費者剩餘下降，因為", "o": ["remaining buyers pay more and some buyers leave the market.", "sellers leave the market.", "willingness to pay rises.", "producer surplus falls."], "a": 0, "e": "兩個原因：原本買家付更多、有人離開。", "oz": ["留下來的買方付更多錢，而且有些買方離開市場", "賣方離開市場", "願付價格上升", "生產者剩餘下降"]}, {"ch": 8, "q": "Without a tax, CS = A+B+C and PS = D+E+F. With a tax, CS = A, PS = F, and tax revenue = B+D. The deadweight loss is", "qz": "沒課稅時 CS = A+B+C、PS = D+E+F。課稅後 CS = A、PS = F、稅收 = B+D。無謂損失是", "o": ["C+E", "B+C+D+E", "B+D", "A+F"], "a": 0, "e": "總剩餘從 A~F 變成 A+B+D+F，少了 C+E。", "h": 1}, {"ch": 8, "q": "Hotel rooms rent for $100 and 1,000 are rented. After a $10 tax per room, 900 are rented. Tax revenue and deadweight loss are", "qz": "旅館房間每間 $100，租出 1,000 間。每間課 $10 的稅後，租出 900 間。稅收和無謂損失分別是", "o": ["$10,000 and $0.", "$8,000 and $500.", "$9,000 and $500.", "$9,000 and $1,000."], "a": 2, "e": "10 × 900 = 9,000；½ × 10 × 100 = 500。", "oz": ["$10,000 和 $0", "$8,000 和 $500", "$9,000 和 $500", "$9,000 和 $1,000"], "h": 1}, {"ch": 8, "q": "A tax rises from $1 to $3 per unit. The deadweight loss is multiplied by about", "qz": "每單位的稅從 $1 提高到 $3。無謂損失大約變成幾倍？", "o": ["3", "6", "9", "1.5"], "oz": ["3 倍", "6 倍", "9 倍", "1.5 倍"], "a": 2, "e": "無謂損失和稅額的平方成正比：稅變 3 倍，DWL 變 3² = 9 倍。", "h": 1}, {"ch": 8, "q": "If labor supply is very inelastic, a tax on labor income has a", "qz": "如果勞動供給非常沒彈性，對勞動所得課稅會有", "o": ["negative effect on revenue.", "zero tax revenue.", "large deadweight loss.", "small deadweight loss."], "a": 3, "e": "供給缺乏彈性 → 工作量幾乎不變 → DWL 小。", "oz": ["對稅收的負面影響", "零稅收", "很大的無謂損失", "很小的無謂損失"]}, {"ch": 9, "q": "The world price is $20. With a $10 tariff, domestic demand falls from 100 to 70 and domestic supply rises from 20 to 40. The deadweight loss of the tariff is", "qz": "世界價格 $20。課 $10 關稅後，國內需求從 100 降到 70，國內供給從 20 增加到 40。關稅的無謂損失是", "o": ["$250", "$300", "$550", "$100"], "oz": ["$250", "$300", "$550", "$100"], "a": 0, "e": "DWL 有兩個三角形：生產過多 ½ × 10 × (40 − 20) = 100，消費過少 ½ × 10 × (100 − 70) = 150，合計 250。$300 是關稅收入 10 × (70 − 40)。", "h": 1}, {"ch": 9, "q": "The deadweight loss of a tariff comes from", "qz": "關稅的無謂損失來自", "o": ["higher producer surplus.", "overproduction and underconsumption.", "lower world prices.", "government revenue."], "a": 1, "e": "D 過度生產、F 消費不足。", "oz": ["生產者剩餘增加", "國內生產過多和消費過少", "世界價格下降", "政府收入"]}, {"ch": 9, "q": "To the argument that \"trade destroys domestic jobs,\" economists respond that", "qz": "對於「貿易會毀掉國內工作」的說法，經濟學家的回應是", "o": ["trade also creates jobs in export industries.", "all imports should be banned.", "trade never affects any jobs.", "quotas are better than tariffs."], "a": 0, "e": "進口減少的工作會被出口產業補回。", "oz": ["貿易也會在出口產業創造工作", "應該禁止所有進口", "貿易從不影響任何工作", "配額比關稅好"]}], "mock-3": [{"ch": 1, "q": "You paid $500 for a nonrefundable concert ticket. On the night, the concert is worth $40 to you, and another activity is worth $60. A rational person should", "qz": "你花 $500 買了一張不能退的演唱會門票。當晚演唱會對你值 $40，另一個活動值 $60。理性的人應該", "o": ["go, because $500 is more than $60.", "skip the concert, because the $500 is a sunk cost and the other activity is worth more.", "go, because the ticket cost $500.", "be indifferent."], "a": 1, "e": "$500 是沉沒成本 (sunk cost)，不影響決策；60 > 40。", "oz": ["去，因為 $500 比 $60 多", "不去演唱會，因為 $500 是沉沒成本，另一個活動價值更高", "去，因為票花了 $500", "兩者無差異"], "h": 1}, {"ch": 1, "q": "Which of the following is NOT part of the opportunity cost of taking a two-week vacation?", "qz": "下列哪一個「不是」去度假兩週的機會成本？", "o": ["Wages you give up from your summer job", "The airfare", "The meals you would have eaten at home anyway", "The hotel bill"], "oz": ["放棄的暑假打工薪水", "機票錢", "反正在家也要吃的伙食", "住旅館的錢"], "a": 2, "e": "機會成本只算「因為這個選擇才多出來」的成本。不度假也要吃飯，所以伙食不算；放棄的薪水雖然沒付錢，但要算。和「上大學的機會成本不含食宿」同一招。", "h": 1}, {"ch": 1, "q": "In the short run, policies that reduce inflation tend to", "qz": "短期內，降低通膨的政策通常會", "o": ["increase productivity.", "increase unemployment.", "decrease unemployment.", "have no effect on unemployment."], "a": 1, "e": "短期通膨和失業反方向。", "oz": ["提高生產力", "提高失業率", "降低失業率", "對失業沒有影響"]}, {"ch": 2, "q": "A new technology raises productivity only in computer production (computers on the horizontal axis). The PPF will", "qz": "新技術只提高電腦（橫軸）的生產力。PPF 會", "o": ["shift outward in parallel.", "rotate outward along the computer axis, leaving the maximum wheat output unchanged.", "stay where it is; the economy just moves along it.", "shift inward."], "oz": ["整條平行往外移", "沿著電腦軸往外轉，最大小麥產量不變", "不動，只是沿著線移動", "往內移"], "a": 1, "e": "如果全部資源都拿去種小麥，新電腦技術沒有幫助，所以縱軸截距不變；橫軸截距變大，PPF 向外「轉」。只有兩種都進步才會平行外移。", "h": 1}, {"ch": 2, "q": "A point inside the production possibilities frontier is", "qz": "生產可能線內部的一點是", "o": ["not possible.", "possible but inefficient.", "a sign of economic growth.", "efficient."], "a": 1, "e": "線內 = 有資源沒用到（例如失業）。", "oz": ["做不到的", "做得到但沒效率", "經濟成長的跡象", "有效率的"]}, {"ch": 2, "q": "Which topic belongs to macroeconomics?", "qz": "哪個主題屬於總體經濟學？", "o": ["a firm's decision about how many workers to hire", "the effect of regulations on auto emissions", "a family's decision about how much to save", "the impact of higher national saving on economic growth"], "a": 3, "e": "整體經濟成長 → 總體。", "oz": ["一家公司決定雇幾個工人", "法規對汽車排放的影響", "一個家庭決定存多少錢", "國民儲蓄增加對經濟成長的影響"]}, {"ch": 3, "q": "If Pat's opportunity cost of making one pizza is 0.5 gallon of root beer, Pat's opportunity cost of one gallon of root beer is", "qz": "如果 Pat 做 1 個披薩的機會成本是 0.5 加侖沙士，那麼 Pat 做 1 加侖沙士的機會成本是", "o": ["0.5 pizza", "1 pizza", "2 pizzas", "4 pizzas"], "oz": ["0.5 個披薩", "1 個披薩", "2 個披薩", "4 個披薩"], "a": 2, "e": "兩種商品的機會成本互為倒數：1 ÷ 0.5 = 2 個披薩。很多人直接選 0.5，這就是陷阱。", "h": 1}, {"ch": 3, "q": "In the same example (Argentina: coffee 2 h, wine 4 h), Argentina's opportunity cost of 1 bottle of wine is", "qz": "同一個例子（阿根廷：咖啡 2 小時、酒 4 小時），阿根廷生產 1 瓶酒的機會成本是", "o": ["4 lb of coffee.", "0.5 lb of coffee.", "2 lb of coffee.", "5 lb of coffee."], "a": 2, "e": "4 小時 ÷ 2 小時 = 2 磅咖啡。", "oz": ["4 磅咖啡", "0.5 磅咖啡", "2 磅咖啡", "5 磅咖啡"]}, {"ch": 3, "q": "An English worker can produce 50 scones or 1 sweater per hour; a Scottish worker 40 scones or 2 sweaters. Scotland will export", "qz": "英格蘭工人每小時能做 50 個司康或 1 件毛衣；蘇格蘭工人能做 40 個司康或 2 件毛衣。蘇格蘭會出口", "o": ["scones.", "sweaters.", "both goods.", "neither good."], "a": 1, "e": "毛衣機會成本：英 50、蘇 20 司康 → 蘇格蘭出口毛衣。", "oz": ["司康", "毛衣", "兩種都出口", "兩種都不出口"]}, {"ch": 3, "q": "Two countries can gain from trade as long as", "qz": "只要怎樣，兩國就能從貿易得利？", "o": ["one has an absolute advantage in both goods.", "their opportunity costs differ.", "they have the same technology.", "they produce the same amount."], "a": 1, "e": "機會成本不同就有比較優勢可利用。", "oz": ["一國在兩種商品都有絕對利益", "兩國的機會成本不同", "兩國技術相同", "兩國產量相同"]}, {"ch": 4, "q": "Which event could cause both the equilibrium price and the equilibrium quantity of tennis balls to rise?", "qz": "下列哪個事件可能讓網球的均衡價格和均衡數量都上升？", "o": ["A fall in the price of tennis rackets", "A rise in the price of rubber", "A new technology that lowers production costs", "Tennis becomes less popular"], "oz": ["網球拍降價", "橡膠漲價", "新技術降低生產成本", "網球變得不受歡迎"], "a": 0, "e": "價格和數量同方向上升 → 需求增加。網球拍是互補品，降價讓更多人打網球 → 網球需求右移。B 是供給減少（P↑Q↓），C 是供給增加（P↓Q↑），D 是需求減少。", "h": 1}, {"ch": 4, "q": "Which of the following shifts the supply of lattes to the right?", "qz": "下列哪一個會使拿鐵的供給線右移？", "o": ["an increase in consumers' income", "a rise in the price of lattes", "a fall in the price of milk", "a rise in the price of coffee beans"], "a": 2, "e": "投入變便宜 → 供給增加。(b) 是沿線移動。", "oz": ["消費者所得增加", "拿鐵價格上漲", "牛奶價格下跌", "咖啡豆價格上漲"]}, {"ch": 4, "q": "If demand increases and supply decreases at the same time, the equilibrium", "qz": "如果需求增加、供給同時減少，均衡", "o": ["quantity rises; price is ambiguous.", "price and quantity both fall.", "price falls; quantity rises.", "price rises; quantity is ambiguous."], "a": 3, "e": "兩個力量都讓價格上漲；數量方向相反所以不確定。", "oz": ["數量增加，價格不確定", "價格和數量都下降", "價格下跌，數量增加", "價格上漲，數量不確定"]}, {"ch": 4, "q": "A new technology reduces the cost of producing hybrid cars. In the hybrid car market,", "qz": "新技術降低了油電混合車的生產成本。在油電車市場，", "o": ["price falls and quantity falls.", "price rises and quantity falls.", "price rises and quantity rises.", "price falls and quantity rises."], "a": 3, "e": "供給右移 → P↓ Q↑。", "oz": ["價格下跌，數量減少", "價格上漲，數量減少", "價格上漲，數量增加", "價格下跌，數量增加"]}, {"ch": 4, "q": "Music CDs and music downloads are substitutes. If the price of CDs falls, in the market for downloads", "qz": "音樂 CD 和音樂下載是替代品。如果 CD 降價，在音樂下載市場中", "o": ["supply shifts right.", "demand shifts left; price and quantity fall.", "demand shifts right; price and quantity rise.", "supply shifts left."], "a": 1, "e": "替代品變便宜 → 下載需求左移。", "oz": ["供給右移", "需求左移，價格和數量都下降", "需求右移，價格和數量都上升", "供給左移"]}, {"ch": 5, "q": "Consumer income rises by 10 percent and the quantity demanded of good X rises by 25 percent. Good X is", "qz": "消費者所得增加 10%，X 的需求量增加 25%。X 是", "o": ["an inferior good.", "a normal good and a necessity.", "a normal good and a luxury.", "a complement."], "oz": ["劣等財", "正常財，也是必需品", "正常財，也是奢侈品", "互補品"], "a": 2, "e": "所得彈性 = 25% ÷ 10% = 2.5。大於 0 是正常財；大於 1 是奢侈品。介於 0 和 1 才是必需品。", "h": 1}, {"ch": 5, "q": "If demand is unit elastic, a decrease in price will", "qz": "如果需求是單一彈性，降價會", "o": ["increase total revenue.", "decrease total revenue.", "leave total revenue unchanged.", "make demand inelastic."], "a": 2, "e": "單一彈性：收益不變。", "oz": ["增加總收益", "減少總收益", "總收益不變", "讓需求變得缺乏彈性"]}, {"ch": 5, "q": "Along a straight-line (linear) demand curve,", "qz": "在一條直線需求線上，", "o": ["elasticity is highest at low prices.", "the elasticity is constant but the slope changes.", "the slope is constant but elasticity is higher at high prices and low quantities.", "the slope and the elasticity are both constant."], "a": 2, "e": "斜率固定、彈性不固定；上端彈性大。", "oz": ["價格低時彈性最大", "彈性固定，但斜率會變", "斜率固定，但價格高、數量少的地方彈性比較大", "斜率和彈性都固定"], "h": 1}, {"ch": 5, "q": "A new hybrid of wheat increases supply. Because the demand for wheat is inelastic, farmers' total revenue", "qz": "新的小麥品種讓供給增加。因為小麥需求缺乏彈性，農夫的總收益會", "o": ["decreases.", "does not change.", "first falls then rises.", "increases."], "a": 0, "e": "價格大跌、數量小增 → 收益下降。", "oz": ["減少", "不變", "先降後升", "增加"]}, {"ch": 5, "q": "A price change causes the quantity demanded to fall by 30 percent while total revenue rises by 15 percent. Demand is", "qz": "價格變動讓需求量下降 30%，總收益卻增加 15%。需求是", "o": ["unit elastic.", "perfectly elastic.", "inelastic.", "elastic."], "a": 2, "e": "收益上升 → 價格漲幅大於數量跌幅 → 缺乏彈性。", "oz": ["單一彈性", "完全有彈性", "缺乏彈性", "富有彈性"], "h": 1}, {"ch": 6, "q": "Before a $3 per-unit tax on buyers, the price was $10. After the tax, sellers receive $8. How much do buyers pay in total per unit, including the tax?", "qz": "對買方課每單位 $3 的稅之前，價格是 $10。課稅後賣方拿到 $8。買方每單位總共付多少（含稅）？", "o": ["$13", "$11", "$10", "$8"], "oz": ["$13", "$11", "$10", "$8"], "a": 1, "e": "買方付的價格 − 賣方拿到的價格 = 稅額 → 買方付 8 + 3 = $11。買方多付 $1，賣方少拿 $2，所以賣方負擔比較多（賣方比較沒彈性）。", "h": 1}, {"ch": 6, "q": "Before a $1.50 tax, pizza sold for $10.00. After the tax, buyers pay $11.00 and sellers receive $9.50. The buyers' share of the tax is", "qz": "課 $1.50 的稅之前，披薩賣 $10.00。課稅後買方付 $11.00，賣方拿 $9.50。買方負擔的稅是", "o": ["$0.", "$1.00.", "$1.50.", "$0.50."], "a": 1, "e": "11 − 10 = 1.00 由買方負擔；賣方負擔 0.50。", "h": 1}, {"ch": 6, "q": "Most of the burden of the 1990 U.S. luxury tax on yachts fell on", "qz": "1990 年美國對遊艇課的奢侈稅，負擔大多落在誰身上？", "o": ["rich buyers of yachts.", "the firms and workers who build yachts.", "foreign countries.", "the government."], "a": 1, "e": "遊艇需求有彈性、供給缺乏彈性。", "oz": ["買遊艇的有錢人", "造遊艇的廠商和工人", "外國", "政府"]}, {"ch": 6, "q": "A price floor set below the equilibrium price", "qz": "訂在均衡價格之下的價格下限", "o": ["causes a surplus.", "causes a shortage.", "has no effect.", "lowers the market price."], "a": 2, "e": "下限在下面 → 不具約束力。", "oz": ["造成過剩", "造成短缺", "沒有影響", "降低市場價格"]}, {"ch": 7, "q": "Demand stays the same while supply decreases. As a result,", "qz": "需求不變、供給減少。結果", "o": ["consumer surplus rises.", "consumer surplus falls.", "consumer surplus is unchanged.", "total surplus rises."], "oz": ["消費者剩餘增加", "消費者剩餘減少", "消費者剩餘不變", "總剩餘增加"], "a": 1, "e": "供給減少 → 價格上漲、數量減少 → 價格線往上，需求線以下、價格以上的三角形變小 → CS 下降。總剩餘也會下降。", "h": 1}, {"ch": 7, "q": "A linear demand curve has a vertical intercept of $60. At a price of $30, quantity demanded is 15. Consumer surplus is", "qz": "一條直線需求線的縱軸截距是 $60。價格 $30 時，需求量是 15。消費者剩餘是", "o": ["$900.", "$150.", "$450.", "$225."], "a": 3, "e": "½ × 15 × 30 = 225。", "h": 1}, {"ch": 7, "q": "Which of the following is NOT a reason why the free-market equilibrium is efficient?", "qz": "下列哪一個「不是」自由市場均衡有效率的原因？", "o": ["The quantity maximizes total surplus.", "It guarantees an equal distribution of well-being.", "Goods are produced by the sellers with the lowest cost.", "Goods go to the buyers who value them most."], "a": 1, "e": "效率不保證公平。", "oz": ["這個數量讓總剩餘最大", "它保證福利平均分配", "商品由成本最低的賣方生產", "商品給了評價最高的買方"]}, {"ch": 7, "q": "A medical procedure costs society $100, but an insured patient pays only $20. As a result,", "qz": "某個醫療處置對社會的成本是 $100，但有保險的病人只付 $20。結果", "o": ["the number of procedures maximizes total surplus.", "producer surplus disappears.", "too few procedures are performed.", "too many procedures are performed and total surplus falls."], "a": 3, "e": "價值低於 $100 的也會做 → 成本 > 價值。", "oz": ["處置次數讓總剩餘最大", "生產者剩餘消失", "處置次數太少", "處置次數太多，總剩餘下降"], "h": 1}, {"ch": 8, "q": "An economy is on the downward-sloping (right) side of the Laffer curve. A cut in the tax rate would", "qz": "一個經濟位在拉弗曲線往下斜的右半邊。調降稅率會", "o": ["reduce tax revenue and increase deadweight loss.", "increase tax revenue and reduce deadweight loss.", "reduce both tax revenue and deadweight loss.", "leave tax revenue unchanged."], "oz": ["減少稅收，增加無謂損失", "增加稅收，減少無謂損失", "稅收和無謂損失都減少", "稅收不變"], "a": 1, "e": "拉弗曲線右半邊代表稅率太高，大家不願意交易，稅基縮很多。這時減稅會讓數量大增，稅收反而增加；稅率變低，DWL 也變小。", "h": 1}, {"ch": 8, "q": "The Laffer curve shows that as the tax rate rises from zero, tax revenue", "qz": "拉弗曲線顯示，稅率從零開始提高時，稅收", "o": ["always rises.", "always falls.", "first rises and then falls.", "stays constant."], "a": 2, "e": "稅太高會讓市場萎縮。", "oz": ["一直增加", "一直減少", "先增加後減少", "維持不變"]}, {"ch": 8, "q": "Airline tickets: without a tax, P = $200 and Q = 100. With a $100 tax, Q = 75. Tax revenue is", "qz": "機票：沒課稅時 P = $200、Q = 100。課 $100 的稅後，Q = 75。稅收是", "o": ["$10,000.", "$7,500.", "$20,000.", "$5,000."], "a": 1, "e": "100 × 75 = 7,500。"}, {"ch": 8, "q": "A tax would cause a larger deadweight loss if placed on", "qz": "課稅造成的無謂損失，在哪一種情況比較大？", "o": ["meals at fancy restaurants than on groceries.", "groceries than on meals at fancy restaurants.", "goods with no substitutes.", "necessities than on luxuries."], "a": 0, "e": "高級餐廳是奢侈品，彈性較大。", "oz": ["課在高級餐廳的餐點比課在生鮮雜貨", "課在生鮮雜貨比課在高級餐廳的餐點", "課在沒有替代品的商品", "課在必需品比課在奢侈品"]}, {"ch": 9, "q": "A small country exports wheat. The world price of wheat rises. In this country,", "qz": "某小國出口小麥。世界小麥價格上漲。在這個國家，", "o": ["producers gain, consumers lose, and total surplus rises.", "consumers gain and producers lose.", "both producers and consumers gain.", "total surplus falls."], "oz": ["生產者得利、消費者受損，總剩餘增加", "消費者得利、生產者受損", "生產者和消費者都得利", "總剩餘下降"], "a": 0, "e": "出口國的國內價格跟著世界價格漲：生產者賣更貴、出口更多；消費者付更多。出口國的生產者得利大於消費者損失，總剩餘增加。", "h": 1}, {"ch": 9, "q": "The world price is $20. With a $10 tariff, domestic demand is 70 and domestic supply is 40. Tariff revenue is", "qz": "世界價格是 $20。課 $10 的關稅後，國內需求是 70，國內供給是 40。關稅收入是", "o": ["$300.", "$550.", "$700.", "$400."], "a": 0, "e": "進口 70 − 40 = 30；10 × 30 = 300。", "h": 1}, {"ch": 9, "q": "If the world price of a good falls, an importing country as a whole", "qz": "如果某商品的世界價格下跌，進口國整體來說會", "o": ["becomes better off.", "becomes worse off.", "must start exporting.", "is unaffected."], "a": 0, "e": "進口國消費者得利更多。", "oz": ["變好", "變差", "必須開始出口", "不受影響"]}]};
